INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 1, 'cabinet-approves-landmark-inland-waterways-transport-project-for-greater-colombo', 'Cabinet Approves Landmark Inland Waterways Transport Project for Greater Colombo', 'බස්නාහිර පළාතේ නව ජල ප්‍රවාහන ව්‍යාපෘතියට කැබිනට් අනුමැතිය හිමිවෙයි', 'மேல் மாகாணத்தில் புதிய நீர்வழிப் போக்குவரத்து திட்டத்திற்கு அமைச்சரவை அனுமதி', 'The Cabinet of Ministers has granted formal approval for a modern passenger boat transport network connecting Battaramulla, Wellawatte, and Colombo Fort.', 'බත්තරමුල්ල, වැල්ලවත්ත සහ කොළඹ කොටුව සම්බන්ධ කරමින් නවීන මගී ප්‍රවාහන බෝට්ටු සේවාවක් ආරම්භ කිරීමට කැබිනට් මණ්ඩලය අනුමැතිය ලබා දී ඇත.', 'பத்தரமுல்ல, வெள்ளவத்தை மற்றும் கொழும்பு கோட்டையை இணைக்கும் நவீன பயணிகள் படகு போக்குவரத்து சேவைக்கு அமைச்சரவை ஒப்புதல் அளித்துள்ளது.', '<p>The Cabinet of Ministers has granted formal approval for a modern passenger boat transport network connecting Battaramulla, Wellawatte, and Colombo Fort.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>බත්තරමුල්ල, වැල්ලවත්ත සහ කොළඹ කොටුව සම්බන්ධ කරමින් නවීන මගී ප්‍රවාහන බෝට්ටු සේවාවක් ආරම්භ කිරීමට කැබිනට් මණ්ඩලය අනුමැතිය ලබා දී ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பத்தரமுல்ல, வெள்ளவத்தை மற்றும் கொழும்பு கோட்டையை இணைக்கும் நவீன பயணிகள் படகு போக்குவரத்து சேவைக்கு அமைச்சரவை ஒப்புதல் அளித்துள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 1, 10, 8627, '2026-10-07 15:48:57', '2026-10-07 15:48:57', '2026-10-07 15:48:57', '[2,3,4,13]', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 'Colombo, Transport, Cabinet, Urban Development, Waterways') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 2, 'southern-expressway-upgrades-begin-to-ease-southern-province-tourism-traffic', 'Southern Expressway Upgrades Begin to Ease Southern Province Tourism Traffic', 'දකුණු අධිවේගී මාර්ගයේ සංචාරක තදබදය අවම කිරීමට නව සංවර්ධන කටයුතු ඇරඹේ', 'தெற்கு அதிவேக நெடுஞ்சாலையில் சுற்றுலாப் போக்குவரத்தைக் குறைக்க புதிய அபிவிருத்திகள் ஆரம்பம்', 'The Road Development Authority has commenced expansion works on key interchanges along the Southern Expressway to facilitate growing holiday and cargo transit.', 'දකුණු පළාතේ සංචාරක ව්‍යාපාරය දිරිගැන්වීම සඳහා දක්ෂිණ ලංකා අධිවේගී මාර්ගයේ ප්‍රධාන පිවිසුම් පුළුල් කිරීමේ කටයුතු ආරම්භ කර තිබේ.', 'தென் மாகாணத்தின் சுற்றுலாத் துறையை மேம்படுத்துவதற்காக தெற்கு அதிவேக நெடுஞ்சாலையின் முக்கிய நுழைவாயில்களை விஸ்தரிக்கும் பணிகள் ஆரம்பிக்கப்பட்டுள்ளன.', '<p>The Road Development Authority has commenced expansion works on key interchanges along the Southern Expressway to facilitate growing holiday and cargo transit.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දකුණු පළාතේ සංචාරක ව්‍යාපාරය දිරිගැන්වීම සඳහා දක්ෂිණ ලංකා අධිවේගී මාර්ගයේ ප්‍රධාන පිවිසුම් පුළුල් කිරීමේ කටයුතු ආරම්භ කර තිබේ.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தென் மாகாணத்தின் சுற்றுலாத் துறையை மேம்படுத்துவதற்காக தெற்கு அதிவேக நெடுஞ்சாலையின் முக்கிய நுழைவாயில்களை விஸ்தரிக்கும் பணிகள் ஆரம்பிக்கப்பட்டுள்ளன.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 7333, '2026-10-07 13:32:17', '2026-10-07 13:32:17', '2026-10-07 13:32:17', '[]', '', 'Southern Expressway, Galle, Tourism, Infrastructure') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 3, 'kandy-esala-perahera-preparations-underway-with-enhanced-cultural-heritage-security', 'Kandy Esala Perahera Preparations Underway with Enhanced Cultural Heritage Security', 'ඓතිහාසික මහනුවර ඇසළ පෙරහැර මංගල්‍යයේ ආරක්ෂාව සහ සංවිධාන කටයුතු පුළුල් කෙරේ', 'வரலாற்று சிறப்புமிக்க கண்டி எசல பெரஹெர பாதுகாப்பும் ஏற்பாடுகளும் பலப்படுத்தப்பட்டன', 'The Sri Dalada Maligawa and Central Province administration have finalized comprehensive arrangements for the grand annual cultural pageant.', 'ශ්‍රී දළදා මාළිගාවේ වාර්ෂික ඇසළ මහා පෙරහැර මංගල්‍යය වෙනුවෙන් විශේෂ ආරක්ෂක වැඩපිළිවෙළක් සහ පහසුකම් සලසා ඇත.', 'ஸ்ரீ தலதா மாளிகையின் வருடாந்த எசல பெரஹெர நிகழ்விற்கான சிறப்பு பாதுகாப்பு ஏற்பாடுகளும் வசதிகளும் பூர்த்தி செய்யப்பட்டுள்ளன.', '<p>The Sri Dalada Maligawa and Central Province administration have finalized comprehensive arrangements for the grand annual cultural pageant.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ශ්‍රී දළදා මාළිගාවේ වාර්ෂික ඇසළ මහා පෙරහැර මංගල්‍යය වෙනුවෙන් විශේෂ ආරක්ෂක වැඩපිළිවෙළක් සහ පහසුකම් සලසා ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஸ்ரீ தலதா மாளிகையின் வருடாந்த எசல பெரஹெர நிகழ்விற்கான சிறப்பு பாதுகாப்பு ஏற்பாடுகளும் வசதிகளும் பூர்த்தி செய்யப்பட்டுள்ளன.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 7342, '2026-10-07 10:12:30', '2026-10-07 10:12:30', '2026-10-07 10:12:30', '[]', '', 'Kandy, Culture, Esala Perahera, Heritage, Sri Lanka') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 4, 'central-highlands-tea-estates-record-surge-in-high-grown-orthodox-crop-yields', 'Central Highlands Tea Estates Record Surge in High-Grown Orthodox Crop Yields', 'මධ්‍යම කඳුකරයේ උඩරට තේ අස්වැන්න කැපී පෙනෙන ලෙස ඉහළ යයි', 'மத்திய மலைநாட்டு உயர் ரக தேயிலை உற்பத்தி கணிசமாக அதிகரிப்பு', 'Favorable weather across Nuwara Eliya and Hatton has propelled high-grown orthodox tea output to its strongest quarterly performance in five years.', 'නුවරඑළිය සහ හැටන් ප්‍රදේශවල පවතින හිතකර කාලගුණය හේතුවෙන් මෙවර උඩරට තේ අස්වැන්න ඉහළ ගොස් ඇත.', 'நுவரெலியா மற்றும் ஹட்டன் பகுதிகளில் நிலவும் சாதகமான வானிலை காரணமாக உயர் ரக தேயிலை உற்பத்தி அதிகரித்துள்ளது.', '<p>Favorable weather across Nuwara Eliya and Hatton has propelled high-grown orthodox tea output to its strongest quarterly performance in five years.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නුවරඑළිය සහ හැටන් ප්‍රදේශවල පවතින හිතකර කාලගුණය හේතුවෙන් මෙවර උඩරට තේ අස්වැන්න ඉහළ ගොස් ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>நுவரெலியா மற்றும் ஹட்டன் பகுதிகளில் நிலவும் சாதகமான வானிலை காரணமாக உயர் ரக தேயிலை உற்பத்தி அதிகரித்துள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 1543, '2026-10-07 07:35:47', '2026-10-07 07:35:47', '2026-10-07 07:35:47', '[]', '', 'Tea, Nuwara Eliya, Agriculture, Exports') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 13, 'mannar-island-coastal-biodiversity-zone-declared-protected-marine-sanctuary', 'Mannar Island Coastal Biodiversity Zone Declared Protected Marine Sanctuary', 'මන්නාරම වෙරළබඩ ජෛව කලාපය ආරක්ෂිත සාගර අභයභූමියක් ලෙස ප්‍රකාශයට පත්කෙරේ', 'மன்னார் கடலோர பல்லுயிர் வலயமானது பாதுகாக்கப்பட்ட கடல் சரணாலயமாக பிரகடனம்', 'The Wildlife Department has gazetted over 15,000 hectares of critical migratory bird habitat and pristine coral reefs as an official national reserve.', 'සංක්‍රමණික පක්ෂීන් සහ කොරල් පර ආරක්ෂා කිරීම වෙනුවෙන් මන්නාරම් බොක්ක ආශ්‍රිත ප්‍රදේශය අභයභූමියක් බවට පත් කර ඇත.', 'வலசைபோகும் பறவைகள் மற்றும் பவளப்பாறைகளை பாதுகாக்கும் நோக்கில் மன்னார் வளைகுடா பகுதி சரணாலயமாக அறிவிக்கப்பட்டுள்ளது.', '<p>The Wildlife Department has gazetted over 15,000 hectares of critical migratory bird habitat and pristine coral reefs as an official national reserve.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සංක්‍රමණික පක්ෂීන් සහ කොරල් පර ආරක්ෂා කිරීම වෙනුවෙන් මන්නාරම් බොක්ක ආශ්‍රිත ප්‍රදේශය අභයභූමියක් බවට පත් කර ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>வலசைபோகும் பறவைகள் மற்றும் பவளப்பாறைகளை பாதுகாக்கும் நோக்கில் மன்னார் வளைகுடா பகுதி சரணாலயமாக அறிவிக்கப்பட்டுள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 1189, '2026-10-07 04:31:14', '2026-10-07 04:31:14', '2026-10-07 04:31:14', '[14,15,16,17]', '', 'Mannar, Environment, Marine Conservation, Wildlife') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 14, 'jaffna-international-airport-expands-daily-regional-commercial-flight-operations', 'Jaffna International Airport Expands Daily Regional Commercial Flight Operations', 'යාපනය ජාත්‍යන්තර ගුවන්තොටුපළේ දෛනික ගුවන් ගමන් වාර සංඛ්‍යාව ඉහළ දමයි', 'யாழ்ப்பாணம் சர்வதேச விமான நிலையத்தின் தினசரி விமான சேவைகள் விஸ்தரிப்பு', 'Palaly Airport will handle double the scheduled flights connecting northern Sri Lanka directly with Chennai and regional hubs from next week.', 'පලාලි ගුවන්තොටුපළ සහ ඉන්දියාවේ චෙන්නායි අතර ගුවන් සේවා තවදුරටත් පුළුල් කිරීමට පියවර ගෙන තිබේ.', 'பலாலி விமான நிலையத்திற்கும் சென்னைக்கும் இடையிலான தினசரி விமான சேவைகள் அடுத்த வாரம் முதல் இரட்டிப்பாக்கப்படவுள்ளன.', '<p>Palaly Airport will handle double the scheduled flights connecting northern Sri Lanka directly with Chennai and regional hubs from next week.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>පලාලි ගුවන්තොටුපළ සහ ඉන්දියාවේ චෙන්නායි අතර ගුවන් සේවා තවදුරටත් පුළුල් කිරීමට පියවර ගෙන තිබේ.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பலாலி விமான நிலையத்திற்கும் சென்னைக்கும் இடையிலான தினசரி விமான சேவைகள் அடுத்த வாரம் முதல் இரட்டிப்பாக்கப்படவுள்ளன.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 3948, '2026-10-07 02:19:54', '2026-10-07 02:19:54', '2026-10-07 02:19:54', '[]', '', 'Jaffna, Aviation, Palaly, India, Travel') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 15, 'colombo-port-container-transshipment-volumes-hit-historic-quarterly-high', 'Colombo Port Container Transshipment Volumes Hit Historic Quarterly High', 'කොළඹ වරායේ බහලුම් මෙහෙයුම් ධාරිතාව නව වාර්තාවක් පිහිටුවයි', 'கொழும்பு துறைமுகத்தின் கொள்கலன் கையாளுகை திறன் புதிய சாதனை படைத்தது', 'The Sri Lanka Ports Authority reported over 2.1 million TEUs handled in Q3, confirming Colombo\'s role as South Asia\'s pre-eminent maritime logistics nexus.', 'කොළඹ වරාය හරහා සිදුකරන ලද බහාලුම් මෙහෙයුම් ප්‍රමාණය ඉතිහාසයේ ඉහළම කාර්තුමය අගය වාර්තා කර ඇත.', 'கொழும்பு துறைமுகத்தின் கொள்கலன் கையாளுகை கொள்ளளவு வரலாற்றில் அதிகூடிய காலாண்டு பதிவை எட்டியுள்ளது.', '<p>The Sri Lanka Ports Authority reported over 2.1 million TEUs handled in Q3, confirming Colombo&#039;s role as South Asia&#039;s pre-eminent maritime logistics nexus.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ වරාය හරහා සිදුකරන ලද බහාලුම් මෙහෙයුම් ප්‍රමාණය ඉතිහාසයේ ඉහළම කාර්තුමය අගය වාර්තා කර ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு துறைமுகத்தின் கொள்கலன் கையாளுகை கொள்ளளவு வரலாற்றில் அதிகூடிய காலாண்டு பதிவை எட்டியுள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 1331, '2026-10-06 22:39:44', '2026-10-06 22:39:44', '2026-10-06 22:39:44', '[]', 'https://www.youtube.com/watch?v=9bZkp7q19f0', 'Colombo Port, Maritime, Shipping, Economy, Logistics') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 16, 'department-of-meteorology-issues-advisory-on-inter-monsoonal-rainfall-patterns', 'Department of Meteorology Issues Advisory on Inter-Monsoonal Rainfall Patterns', 'අන්තර් මෝසම් වැසි තත්ත්වය පිළිබඳ කාලගුණ විද්‍යා දෙපාර්තමේන්තුවෙන් අනතුරු ඇඟවීමක්', 'பருவமழை மாற்றங்கள் குறித்து வளிமண்டலவியல் திணைக்களம் எச்சரிக்கை', 'Thunderstorms and temporary localized gusts are anticipated across Western, Sabaragamuwa, and Southern provinces over the weekend.', 'බස්නාහිර, සබරගමුව සහ දකුණු පළාත්වල සවස් කාලයේ ගිගුරුම් සහිත වැසි ඇතිවිය හැකි බවට කාලගුණ අංශ අනතුරු අඟවයි.', 'மேல், சப்ரகமுவ மற்றும் தென் மாகாணங்களில் இடியுடன் கூடிய மழை பெய்யக்கூடும் என வளிமண்டலவியல் திணைக்களம் எச்சரித்துள்ளது.', '<p>Thunderstorms and temporary localized gusts are anticipated across Western, Sabaragamuwa, and Southern provinces over the weekend.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>බස්නාහිර, සබරගමුව සහ දකුණු පළාත්වල සවස් කාලයේ ගිගුරුම් සහිත වැසි ඇතිවිය හැකි බවට කාලගුණ අංශ අනතුරු අඟවයි.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>மேல், சப்ரகமுவ மற்றும் தென் மாகாணங்களில் இடியுடன் கூடிய மழை பெய்யக்கூடும் என வளிமண்டலவியல் திணைக்களம் எச்சரித்துள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9522, '2026-10-06 20:13:48', '2026-10-06 20:13:48', '2026-10-06 20:13:48', '[]', '', 'Weather, Meteorology, Rainfall, Advisory') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 17, 'free-health-screening-clinics-launched-across-rural-hospitals-in-polonnaruwa', 'Free Health Screening Clinics Launched Across Rural Hospitals in Polonnaruwa', 'පොළොන්නරුවේ ග්‍රාමීය රෝහල් ආශ්‍රිතව නොමිලේ සෞඛ්‍ය පරීක්ෂණ සායන ඇරඹේ', 'பொலன்னறுவையில் இலவச சுகாதார பரிசோதனை முகாம்கள் ஆரம்பம்', 'The Ministry of Health has deployed specialized mobile screening units to identify early non-communicable diseases in farming communities.', 'ගොවි ජනතාවගේ සෞඛ්‍ය තත්ත්වය නංවාලීම වෙනුවෙන් පොළොන්නරුව දිස්ත්‍රික්කයේ නොමිලේ වෛද්‍ය සායන මාලාවක් ආරම්භ කර ඇත.', 'விவசாய மக்களின் நலனைக் கருத்தில் கொண்டு பொலன்னறுவை மாவட்டத்தில் இலவச மருத்துவ முகாம்கள் ஆரம்பிக்கப்பட்டுள்ளன.', '<p>The Ministry of Health has deployed specialized mobile screening units to identify early non-communicable diseases in farming communities.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ගොවි ජනතාවගේ සෞඛ්‍ය තත්ත්වය නංවාලීම වෙනුවෙන් පොළොන්නරුව දිස්ත්‍රික්කයේ නොමිලේ වෛද්‍ය සායන මාලාවක් ආරම්භ කර ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>விவசாய மக்களின் நலனைக் கருத்தில் கொண்டு பொலன்னறுவை மாவட்டத்தில் இலவச மருத்துவ முகாம்கள் ஆரம்பிக்கப்பட்டுள்ளன.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 4688, '2026-10-06 17:11:22', '2026-10-06 17:11:22', '2026-10-06 17:11:22', '[18,19,20,22]', '', 'Health, Polonnaruwa, Public Health, Hospitals') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 18, 'new-railway-signal-modernization-commissioned-on-northern-coastal-line', 'New Railway Signal Modernization Commissioned on Northern Coastal Line', 'උතුරු වෙරළබඩ දුම්රිය මාර්ගයේ නවීන සංඥා පද්ධතිය විවෘත කෙරේ', 'வடக்கு கடலோர புகையிரத பாதையில் நவீன சமிக்ஞை கட்டமைப்பு திறப்பு', 'Automatic color light signaling and upgraded level crossings between Mahawa and Anuradhapura have reduced commuter journey times by 25 minutes.', 'මහව සිට අනුරාධපුර දක්වා නවීන වර්ණ සංඥා පද්ධතිය සක්‍රිය කිරීමත් සමඟ දුම්රිය ගමනාගමනය වඩාත් ආරක්ෂිත වී තිබේ.', 'மஹவ முதல் அனுராதபுரம் வரையிலான நவீன சமிக்ஞை முறைமை செயற்படுத்தப்பட்டதன் மூலம் பயண நேரம் குறைக்கப்பட்டுள்ளது.', '<p>Automatic color light signaling and upgraded level crossings between Mahawa and Anuradhapura have reduced commuter journey times by 25 minutes.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මහව සිට අනුරාධපුර දක්වා නවීන වර්ණ සංඥා පද්ධතිය සක්‍රිය කිරීමත් සමඟ දුම්රිය ගමනාගමනය වඩාත් ආරක්ෂිත වී තිබේ.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>மஹவ முதல் அனுராதபுரம் வரையிலான நவீன சமிக்ஞை முறைமை செயற்படுத்தப்பட்டதன் மூலம் பயண நேரம் குறைக்கப்பட்டுள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6484, '2026-10-06 14:07:26', '2026-10-06 14:07:26', '2026-10-06 14:07:26', '[]', '', 'Railways, Transport, Anuradhapura, Infrastructure') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 19, 'national-consumer-price-index-drops-as-food-distribution-network-strengthens', 'National Consumer Price Index Drops as Food Distribution Network Strengthens', 'ආහාර ද්‍රව්‍ය බෙදාහැරීම විධිමත් වීමත් සමඟ පාරිභෝගික මිල දර්ශකය පහළට', 'உணவு விநியோகம் சீரானதால் நுகர்வோர் விலைச் சுட்டெண் வீழ்ச்சி', 'Direct farm-to-market agricultural economic centers in Dambulla and Thambuthegama helped drive essential vegetable prices down across urban retail hubs.', 'දඹුල්ල සහ තඹුත්තේගම ආර්ථික මධ්‍යස්ථාන හරහා එළවළු බෙදාහැරීම සාර්ථක වීමෙන් වෙළෙඳපොළ මිල ගණන් පහත වැටී ඇත.', 'தம்புள்ளை பொருளாதார மத்திய நிலையத்தின் ஊடாக மரக்கறி விநியோகம் சீரானதால் சந்தை விலைகள் குறைவடைந்துள்ளன.', '<p>Direct farm-to-market agricultural economic centers in Dambulla and Thambuthegama helped drive essential vegetable prices down across urban retail hubs.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දඹුල්ල සහ තඹුත්තේගම ආර්ථික මධ්‍යස්ථාන හරහා එළවළු බෙදාහැරීම සාර්ථක වීමෙන් වෙළෙඳපොළ මිල ගණන් පහත වැටී ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தம்புள்ளை பொருளாதார மத்திய நிலையத்தின் ஊடாக மரக்கறி விநியோகம் சீரானதால் சந்தை விலைகள் குறைவடைந்துள்ளன.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2762, '2026-10-06 12:02:49', '2026-10-06 12:02:49', '2026-10-06 12:02:49', '[]', '', 'Economy, Markets, Prices, Agriculture, Dambulla') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 20, 'university-of-peradeniya-engineering-faculty-unveils-indigenous-solar-tracker', 'University of Peradeniya Engineering Faculty Unveils Indigenous Solar Tracker', 'පේරාදෙණිය විශ්වවිද්‍යාලයේ ඉංජිනේරු පීඨයෙන් නව සූර්ය බලශක්ති පද්ධතියක්', 'பேராதனை பல்கலைக்கழக பொறியியல் பீடத்தினால் புதிய சூரிய சக்தி கட்டமைப்பு அறிமுகம்', 'Undergraduate researchers have patented a dual-axis algorithm that increases rooftop photovoltaic efficiency by up to 34% in tropical climates.', 'ශ්‍රී ලංකාවේ නිවර්තන දේශගුණයට ගැළපෙන ඉහළ කාර්යක්ෂමතාවයකින් යුත් සූර්ය බලශක්ති ලුහුබැඳීමේ පද්ධතියක් පේරාදෙණියෙන් නිපදවයි.', 'இலங்கையின் காலநிலைக்கு ஏற்ற அதிக திறன் கொண்ட சூரிய சக்தி கண்காணிப்பு அமைப்பை பேராதனை பொறியியலாளர்கள் உருவாக்கியுள்ளனர்.', '<p>Undergraduate researchers have patented a dual-axis algorithm that increases rooftop photovoltaic efficiency by up to 34% in tropical climates.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ශ්‍රී ලංකාවේ නිවර්තන දේශගුණයට ගැළපෙන ඉහළ කාර්යක්ෂමතාවයකින් යුත් සූර්ය බලශක්ති ලුහුබැඳීමේ පද්ධතියක් පේරාදෙණියෙන් නිපදවයි.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கையின் காலநிலைக்கு ஏற்ற அதிக திறன் கொண்ட சூரிய சக்தி கண்காணிப்பு அமைப்பை பேராதனை பொறியியலாளர்கள் உருவாக்கியுள்ளனர்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6685, '2026-10-06 09:20:26', '2026-10-06 09:20:26', '2026-10-06 09:20:26', '[]', '', 'Education, University of Peradeniya, Solar, Innovation') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 22, 'trincomalee-deep-water-harbour-master-plan-attracts-multi-billion-port-investment', 'Trincomalee Deep-Water Harbour Master Plan Attracts Multi-Billion Port Investment', 'ත්‍රිකුණාමලය ස්වභාවික වරාය සංවර්ධන සැලැස්මට දැවැන්ත විදෙස් ආයෝජන', 'திருகோணமலை துறைமுக அபிவிருத்தி திட்டத்திற்கு பாரிய வெளிநாட்டு முதலீடுகள்', 'International shipping consortia have submitted detailed feasibility studies to build bulk cargo terminals, bunkering hubs, and industrial warehousing.', 'ත්‍රිකුණාමලය වරාය ආශ්‍රිතව නව තොග බඩු පර්යන්ත සහ කර්මාන්ත කලාප පිහිටුවීමට විදෙස් සමාගම් ගිවිසුම්ගත වෙයි.', 'திருகோணமலை துறைமுகத்தை அண்டி புதிய சரக்கு முனையங்கள் மற்றும் கைத்தொழில் வலயங்களை அமைக்க வெளிநாட்டு நிறுவனங்கள் விருப்பம்.', '<p>International shipping consortia have submitted detailed feasibility studies to build bulk cargo terminals, bunkering hubs, and industrial warehousing.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ත්‍රිකුණාමලය වරාය ආශ්‍රිතව නව තොග බඩු පර්යන්ත සහ කර්මාන්ත කලාප පිහිටුවීමට විදෙස් සමාගම් ගිවිසුම්ගත වෙයි.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>திருகோணமலை துறைமுகத்தை அண்டி புதிய சரக்கு முனையங்கள் மற்றும் கைத்தொழில் வலயங்களை அமைக்க வெளிநாட்டு நிறுவனங்கள் விருப்பம்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 1, 10, 6078, '2026-10-06 05:48:49', '2026-10-06 05:48:49', '2026-10-06 05:48:49', '[23,24,25,26]', 'https://www.youtube.com/watch?v=kJQP7kiw5Fk', 'Trincomalee, Port, Investment, Maritime, Economy') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 23, 'national-gem-and-jewellery-authority-hosts-annual-ratnapura-international-exhibition', 'National Gem and Jewellery Authority Hosts Annual Ratnapura International Exhibition', 'රත්නපුර ජාත්‍යන්තර මැණික් හා ස්වර්ණාභරණ ප්‍රදර්ශනය සාර්ථකව ඇරඹෙයි', 'இரத்தினபுரி சர்வதேச இரத்தினக்கல் மற்றும் ஆபரண கண்காட்சி ஆரம்பம்', 'Foreign buyers from over 40 countries arrived in the City of Gems to trade world-renowned Ceylon Blue Sapphires, Padparadscha, and artisanal jewelry.', 'ලොව සුප්‍රසිද්ධ ලංකා නිල් මැණික් සහ ස්වර්ණාභරණ අලෙවිය වෙනුවෙන් රත්නපුරයේදී ජාත්‍යන්තර ප්‍රදර්ශනයක් ඇරඹී ඇත.', 'பிரசித்தி பெற்ற இலங்கை நீல மாணிக்கங்கள் மற்றும் ஆபரண விற்பனைக்கான சர்வதேச கண்காட்சி இரத்தினபுரியில் ஆரம்பமாகியுள்ளது.', '<p>Foreign buyers from over 40 countries arrived in the City of Gems to trade world-renowned Ceylon Blue Sapphires, Padparadscha, and artisanal jewelry.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ලොව සුප්‍රසිද්ධ ලංකා නිල් මැණික් සහ ස්වර්ණාභරණ අලෙවිය වෙනුවෙන් රත්නපුරයේදී ජාත්‍යන්තර ප්‍රදර්ශනයක් ඇරඹී ඇත.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பிரசித்தி பெற்ற இலங்கை நீல மாணிக்கங்கள் மற்றும் ஆபரண விற்பனைக்கான சர்வதேச கண்காட்சி இரத்தினபுரியில் ஆரம்பமாகியுள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 7269, '2026-10-06 02:54:35', '2026-10-06 02:54:35', '2026-10-06 02:54:35', '[]', '', 'Gems, Ratnapura, Blue Sapphire, Exports, Trade') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 1, 24, 'fisheries-ministry-deploys-modern-satellite-vessel-monitoring-for-deep-sea-fleet', 'Fisheries Ministry Deploys Modern Satellite Vessel Monitoring for Deep-Sea Fleet', 'මෙරට බහුදින ධීවර යාත්‍රා සඳහා චන්ද්‍රිකා තාක්ෂණික නිරීක්ෂණ පද්ධතියක්', 'ஆழ்கடல் மீன்பிடி படகுகளுக்கு புதிய செய்மதி கண்காணிப்பு கட்டமைப்பு', 'Over 3,500 multi-day fishing craft will now be equipped with real-time digital distress transponders to guarantee maritime safety and curb illegal incursions.', 'ගැඹුරු මුහුදේ යාත්‍රා කරන ධීවරයින්ගේ ආරක්ෂාව තහවුරු කිරීමට සහ අනතුරු අවම කිරීමට නව චන්ද්‍රිකා සන්නිවේදන ක්‍රමවේදයක් හඳුන්වා දී තිබේ.', 'ஆழ்கடல் மீனவர்களின் பாதுகாப்பை உறுதிப்படுத்தவும் விபத்துகளைத் தவிர்க்கவும் புதிய செய்மதி தொடர்பாடல் கட்டமைப்பு அறிமுகப்படுத்தப்பட்டுள்ளது.', '<p>Over 3,500 multi-day fishing craft will now be equipped with real-time digital distress transponders to guarantee maritime safety and curb illegal incursions.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ගැඹුරු මුහුදේ යාත්‍රා කරන ධීවරයින්ගේ ආරක්ෂාව තහවුරු කිරීමට සහ අනතුරු අවම කිරීමට නව චන්ද්‍රිකා සන්නිවේදන ක්‍රමවේදයක් හඳුන්වා දී තිබේ.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஆழ்கடல் மீனவர்களின் பாதுகாப்பை உறுதிப்படுத்தவும் விபத்துகளைத் தவிர்க்கவும் புதிய செய்மதி தொடர்பாடல் கட்டமைப்பு அறிமுகப்படுத்தப்பட்டுள்ளது.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8206, '2026-10-06 00:42:59', '2026-10-06 00:42:59', '2026-10-06 00:42:59', '[]', '', 'Fisheries, Maritime, Safety, Technology') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 25, 'speaker-convenes-special-parliamentary-session-on-annual-fiscal-reform-budget', 'Speaker Convenes Special Parliamentary Session on Annual Fiscal Reform Budget', 'වාර්ෂික මූල්‍ය ප්‍රතිසංස්කරණ අයවැය පිළිබඳ විශේෂ පාර්ලිමේන්තු විවාදය ඇරඹෙයි', 'வருடாந்த நிதி சீர்திருத்த வரவு செலவு திட்டம் தொடர்பான விசேட பாராளுமன்ற அமர்வு', 'Speaker Convenes Special Parliamentary Session on Annual Fiscal Reform Budget. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'වාර්ෂික මූල්‍ය ප්‍රතිසංස්කරණ අයවැය පිළිබඳ විශේෂ පාර්ලිමේන්තු විවාදය ඇරඹෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'வருடாந்த நிதி சீர்திருத்த வரவு செலவு திட்டம் தொடர்பான விசேட பாராளுமன்ற அமர்வு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Speaker Convenes Special Parliamentary Session on Annual Fiscal Reform Budget. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>වාර්ෂික මූල්‍ය ප්‍රතිසංස්කරණ අයවැය පිළිබඳ විශේෂ පාර්ලිමේන්තු විවාදය ඇරඹෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>வருடாந்த நிதி சீர்திருத்த வரவு செலவு திட்டம் தொடர்பான விசேட பாராளுமன்ற அமர்வு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 7365, '2026-10-05 21:56:24', '2026-10-05 21:56:24', '2026-10-05 21:56:24', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 26, 'election-commission-finalizes-updated-electoral-register-across-all-22-districts', 'Election Commission Finalizes Updated Electoral Register Across All 22 Districts', 'මැතිවරණ කොමිෂන් සභාව දිස්ත්‍රික්ක 22 ක ඡන්ද නාමලේඛන යාවත්කාලීන කිරීම අවසන් කරයි', 'தேர்தல் ஆணைக்குழு 22 மாவட்டங்களின் வாக்காளர் பதிவேடுகளை புதுப்பிக்கும் பணியை நிறைவு செய்தது', 'Election Commission Finalizes Updated Electoral Register Across All 22 Districts. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මැතිවරණ කොමිෂන් සභාව දිස්ත්‍රික්ක 22 ක ඡන්ද නාමලේඛන යාවත්කාලීන කිරීම අවසන් කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'தேர்தல் ஆணைக்குழு 22 மாவட்டங்களின் வாக்காளர் பதிவேடுகளை புதுப்பிக்கும் பணியை நிறைவு செய்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Election Commission Finalizes Updated Electoral Register Across All 22 Districts. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මැතිවරණ කොමිෂන් සභාව දිස්ත්‍රික්ක 22 ක ඡන්ද නාමලේඛන යාවත්කාලීන කිරීම අවසන් කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தேர்தல் ஆணைக்குழு 22 மாவட்டங்களின் வாக்காளர் பதிவேடுகளை புதுப்பிக்கும் பணியை நிறைவு செய்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6426, '2026-10-05 18:41:04', '2026-10-05 18:41:04', '2026-10-05 18:41:04', '[27,28,29,30]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 27, 'parliamentary-committee-on-public-finance-examines-customs-revenue-automation', 'Parliamentary Committee on Public Finance Examines Customs Revenue Automation', 'රේගු ආදායම් කළමනාකරණය ඩිජිටල්කරණය කිරීම පිළිබඳ කෝපා කමිටුවේ අවධානය', 'சுங்க வருமான முகாமைத்துவத்தை டிஜிட்டல் மயமாக்குவது குறித்து பாராளுமன்ற குழு ஆய்வு', 'Parliamentary Committee on Public Finance Examines Customs Revenue Automation. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'රේගු ආදායම් කළමනාකරණය ඩිජිටල්කරණය කිරීම පිළිබඳ කෝපා කමිටුවේ අවධානය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சுங்க வருமான முகாமைத்துவத்தை டிஜிட்டல் மயமாக்குவது குறித்து பாராளுமன்ற குழு ஆய்வு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Parliamentary Committee on Public Finance Examines Customs Revenue Automation. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>රේගු ආදායම් කළමනාකරණය ඩිජිටල්කරණය කිරීම පිළිබඳ කෝපා කමිටුවේ අවධානය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சுங்க வருமான முகாமைத்துவத்தை டிஜிட்டல் மயமாக்குவது குறித்து பாராளுமன்ற குழு ஆய்வு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8952, '2026-10-05 16:11:00', '2026-10-05 16:11:00', '2026-10-05 16:11:00', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 28, 'president-chairs-bilateral-economic-cooperation-meeting-at-presidential-secretariat', 'President Chairs Bilateral Economic Cooperation Meeting at Presidential Secretariat', 'ජනාධිපති ලේකම් කාර්යාලයේදී ද්විපාර්ශ්වික ආර්ථික සබඳතා පිළිබඳ ඉහළ පෙළේ සාකච්ඡාවක්', 'ஜனாதிபதி செயலகத்தில் இருதரப்பு பொருளாதார ஒத்துழைப்பு தொடர்பான உயர்மட்ட கலந்துரையாடல்', 'President Chairs Bilateral Economic Cooperation Meeting at Presidential Secretariat. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ජනාධිපති ලේකම් කාර්යාලයේදී ද්විපාර්ශ්වික ආර්ථික සබඳතා පිළිබඳ ඉහළ පෙළේ සාකච්ඡාවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஜனாதிபதி செயலகத்தில் இருதரப்பு பொருளாதார ஒத்துழைப்பு தொடர்பான உயர்மட்ட கலந்துரையாடல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>President Chairs Bilateral Economic Cooperation Meeting at Presidential Secretariat. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ජනාධිපති ලේකම් කාර්යාලයේදී ද්විපාර්ශ්වික ආර්ථික සබඳතා පිළිබඳ ඉහළ පෙළේ සාකච්ඡාවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஜனாதிபதி செயலகத்தில் இருதரப்பு பொருளாதார ஒத்துழைப்பு தொடர்பான உயர்மட்ட கலந்துரையாடல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5475, '2026-10-05 13:00:31', '2026-10-05 13:00:31', '2026-10-05 13:00:31', '[]', 'https://www.youtube.com/watch?v=fJ9rUzIMcZQ', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 29, 'new-anti-corruption-commission-operational-framework-tabled-in-parliament', 'New Anti-Corruption Commission Operational Framework Tabled in Parliament', 'දූෂණ විරෝධී නව පනත් කෙටුම්පතේ ක්‍රියාකාරී සැලැස්ම පාර්ලිමේන්තුවට ඉදිරිපත් කෙරේ', 'புதிய ஊழல் எதிர்ப்பு சட்டத்தின் செயற்பாட்டு வரைபு பாராளுமன்றத்தில் சமர்ப்பிப்பு', 'New Anti-Corruption Commission Operational Framework Tabled in Parliament. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'දූෂණ විරෝධී නව පනත් කෙටුම්පතේ ක්‍රියාකාරී සැලැස්ම පාර්ලිමේන්තුවට ඉදිරිපත් කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'புதிய ஊழல் எதிர்ப்பு சட்டத்தின் செயற்பாட்டு வரைபு பாராளுமன்றத்தில் சமர்ப்பிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>New Anti-Corruption Commission Operational Framework Tabled in Parliament. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දූෂණ විරෝධී නව පනත් කෙටුම්පතේ ක්‍රියාකාරී සැලැස්ම පාර්ලිමේන්තුවට ඉදිරිපත් කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>புதிய ஊழல் எதிர்ப்பு சட்டத்தின் செயற்பாட்டு வரைபு பாராளுமன்றத்தில் சமர்ப்பிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9518, '2026-10-05 10:16:00', '2026-10-05 10:16:00', '2026-10-05 10:16:00', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 30, 'public-administration-ministry-announces-comprehensive-civil-service-digitization', 'Public Administration Ministry Announces Comprehensive Civil Service Digitization', 'රාජ්‍ය සේවයේ සියලු සේවාවන් කඩිනමින් ඩිජිටල්කරණය කිරීමට නව චක්‍රලේඛයක්', 'அரச சேவைகளை உடனடியாக டிஜிட்டல் மயமாக்க புதிய சுற்றுநிருபம் வெளியீடு', 'Public Administration Ministry Announces Comprehensive Civil Service Digitization. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'රාජ්‍ය සේවයේ සියලු සේවාවන් කඩිනමින් ඩිජිටල්කරණය කිරීමට නව චක්‍රලේඛයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'அரச சேவைகளை உடனடியாக டிஜிட்டல் மயமாக்க புதிய சுற்றுநிருபம் வெளியீடு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Public Administration Ministry Announces Comprehensive Civil Service Digitization. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>රාජ්‍ය සේවයේ සියලු සේවාවන් කඩිනමින් ඩිජිටල්කරණය කිරීමට නව චක්‍රලේඛයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>அரச சேவைகளை உடனடியாக டிஜிட்டல் மயமாக்க புதிய சுற்றுநிருபம் வெளியீடு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9141, '2026-10-05 07:13:11', '2026-10-05 07:13:11', '2026-10-05 07:13:11', '[31,32,33,34]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 31, 'judicial-services-commission-appoints-new-high-court-judges-to-regional-circuits', 'Judicial Services Commission Appoints New High Court Judges to Regional Circuits', 'මහාධිකරණ විනිසුරුවරුන් පිරිසකට නව පත්වීම් ප්‍රදානය කෙරේ', 'மேல் நீதிமன்ற நீதிபதிகளுக்கு புதிய நியமனங்கள் வழங்கப்பட்டன', 'Judicial Services Commission Appoints New High Court Judges to Regional Circuits. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මහාධිකරණ විනිසුරුවරුන් පිරිසකට නව පත්වීම් ප්‍රදානය කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'மேல் நீதிமன்ற நீதிபதிகளுக்கு புதிய நியமனங்கள் வழங்கப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Judicial Services Commission Appoints New High Court Judges to Regional Circuits. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මහාධිකරණ විනිසුරුවරුන් පිරිසකට නව පත්වීම් ප්‍රදානය කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>மேல் நீதிமன்ற நீதிபதிகளுக்கு புதிய நியமனங்கள் வழங்கப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 5886, '2026-10-05 04:54:29', '2026-10-05 04:54:29', '2026-10-05 04:54:29', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 32, 'national-security-council-reviews-maritime-boundary-surveillance-protocols', 'National Security Council Reviews Maritime Boundary Surveillance Protocols', 'මුහුදු සීමා ආරක්ෂාව තර කිරීම පිළිබඳ ජාතික ආරක්ෂක මණ්ඩලයේ විශේෂ සමාලෝචනයක්', 'கடல் எல்லை பாதுகாப்பை பலப்படுத்துவது குறித்து தேசிய பாதுகாப்பு சபை மீளாய்வு', 'National Security Council Reviews Maritime Boundary Surveillance Protocols. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මුහුදු සීමා ආරක්ෂාව තර කිරීම පිළිබඳ ජාතික ආරක්ෂක මණ්ඩලයේ විශේෂ සමාලෝචනයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கடல் எல்லை பாதுகாப்பை பலப்படுத்துவது குறித்து தேசிய பாதுகாப்பு சபை மீளாய்வு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Security Council Reviews Maritime Boundary Surveillance Protocols. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මුහුදු සීමා ආරක්ෂාව තර කිරීම පිළිබඳ ජාතික ආරක්ෂක මණ්ඩලයේ විශේෂ සමාලෝචනයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கடல் எல்லை பாதுகாப்பை பலப்படுத்துவது குறித்து தேசிய பாதுகாப்பு சபை மீளாய்வு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2814, '2026-10-05 01:59:56', '2026-10-05 01:59:56', '2026-10-05 01:59:56', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 33, 'parliament-approves-strengthened-consumer-protection-and-monopoly-control-bill', 'Parliament Approves Strengthened Consumer Protection and Monopoly Control Bill', 'පාරිභෝගික ආරක්ෂණ සහ ඒකාධිකාරී වෙළෙඳපොළ පාලන නව පනත සම්මත වෙයි', 'நுகர்வோர் பாதுகாப்பு மற்றும் சந்தை கட்டுப்பாட்டு புதிய சட்டம் நிறைவேற்றப்பட்டது', 'Parliament Approves Strengthened Consumer Protection and Monopoly Control Bill. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'පාරිභෝගික ආරක්ෂණ සහ ඒකාධිකාරී වෙළෙඳපොළ පාලන නව පනත සම්මත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'நுகர்வோர் பாதுகாப்பு மற்றும் சந்தை கட்டுப்பாட்டு புதிய சட்டம் நிறைவேற்றப்பட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Parliament Approves Strengthened Consumer Protection and Monopoly Control Bill. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>පාරිභෝගික ආරක්ෂණ සහ ඒකාධිකාරී වෙළෙඳපොළ පාලන නව පනත සම්මත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>நுகர்வோர் பாதுகாப்பு மற்றும் சந்தை கட்டுப்பாட்டு புதிய சட்டம் நிறைவேற்றப்பட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2600, '2026-10-04 22:47:13', '2026-10-04 22:47:13', '2026-10-04 22:47:13', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 34, 'foreign-minister-addresses-colombo-diplomatic-corps-on-international-treaties', 'Foreign Minister Addresses Colombo Diplomatic Corps on International Treaties', 'විදේශ අමාත්‍යවරයා කොළඹ රාජ්‍ය තාන්ත්‍රික ප්‍රධානීන් අමතා විශේෂ ප්‍රකාශයක් කරයි', 'வெளிவிவகார அமைச்சர் கொழும்பில் உள்ள தூதுவர்களை சந்தித்து முக்கிய உரை', 'Foreign Minister Addresses Colombo Diplomatic Corps on International Treaties. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'විදේශ අමාත්‍යවරයා කොළඹ රාජ්‍ය තාන්ත්‍රික ප්‍රධානීන් අමතා විශේෂ ප්‍රකාශයක් කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'வெளிவிவகார அமைச்சர் கொழும்பில் உள்ள தூதுவர்களை சந்தித்து முக்கிய உரை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Foreign Minister Addresses Colombo Diplomatic Corps on International Treaties. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>විදේශ අමාත්‍යවරයා කොළඹ රාජ්‍ය තාන්ත්‍රික ප්‍රධානීන් අමතා විශේෂ ප්‍රකාශයක් කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>வெளிவிவகார அமைச்சர் கொழும்பில் உள்ள தூதுவர்களை சந்தித்து முக்கிய உரை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 5070, '2026-10-04 20:11:56', '2026-10-04 20:11:56', '2026-10-04 20:11:56', '[35,36,37,38]', 'https://www.youtube.com/watch?v=kXYiU_JCYtU', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 35, 'local-government-authorities-transition-to-centralized-e-governance-civic-portal', 'Local Government Authorities Transition to Centralized E-Governance Civic Portal', 'පළාත් පාලන ආයතනවල මහජන සේවාවන් මාර්ගගත ක්‍රමයට එක්කෙරේ', 'உள்ளூராட்சி மன்றங்களின் பொது சேவைகள் இணையவழி கட்டமைப்பிற்கு மாற்றப்பட்டன', 'Local Government Authorities Transition to Centralized E-Governance Civic Portal. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'පළාත් පාලන ආයතනවල මහජන සේවාවන් මාර්ගගත ක්‍රමයට එක්කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'உள்ளூராட்சி மன்றங்களின் பொது சேவைகள் இணையவழி கட்டமைப்பிற்கு மாற்றப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Local Government Authorities Transition to Centralized E-Governance Civic Portal. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>පළාත් පාලන ආයතනවල මහජන සේවාවන් මාර්ගගත ක්‍රමයට එක්කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>உள்ளூராட்சி மன்றங்களின் பொது சேவைகள் இணையவழி கட்டமைப்பிற்கு மாற்றப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6816, '2026-10-04 17:13:14', '2026-10-04 17:13:14', '2026-10-04 17:13:14', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 36, 'constitutional-council-reviews-nominations-for-independent-oversight-commissions', 'Constitutional Council Reviews Nominations for Independent Oversight Commissions', 'ස්වාධීන කොමිෂන් සභා සඳහා නව සාමාජිකයින් නම් කිරීමට ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව රැස්වෙයි', 'சுயாதீன ஆணைக்குழுக்களுக்கான நியமனங்களை பரிசீலிக்க அரசியலமைப்பு பேரவை கூடியது', 'Constitutional Council Reviews Nominations for Independent Oversight Commissions. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ස්වාධීන කොමිෂන් සභා සඳහා නව සාමාජිකයින් නම් කිරීමට ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව රැස්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சுயாதீன ஆணைக்குழுக்களுக்கான நியமனங்களை பரிசீலிக்க அரசியலமைப்பு பேரவை கூடியது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Constitutional Council Reviews Nominations for Independent Oversight Commissions. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ස්වාධීන කොමිෂන් සභා සඳහා නව සාමාජිකයින් නම් කිරීමට ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව රැස්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சுயாதீன ஆணைக்குழுக்களுக்கான நியமனங்களை பரிசீலிக்க அரசியலமைப்பு பேரவை கூடியது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 3712, '2026-10-04 14:19:19', '2026-10-04 14:19:19', '2026-10-04 14:19:19', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 37, 'minister-of-justice-outlines-comprehensive-modernization-of-commercial-courts', 'Minister of Justice Outlines Comprehensive Modernization of Commercial Courts', 'වාණිජ මහාධිකරණ පද්ධතිය කඩිනම් නඩු විභාග සඳහා නවීකරණය කෙරේ', 'வணிக நீதிமன்ற கட்டமைப்பில் துரித வழக்கு விசாரணைக்கான நவீன மாற்றங்கள்', 'Minister of Justice Outlines Comprehensive Modernization of Commercial Courts. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'වාණිජ මහාධිකරණ පද්ධතිය කඩිනම් නඩු විභාග සඳහා නවීකරණය කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'வணிக நீதிமன்ற கட்டமைப்பில் துரித வழக்கு விசாரணைக்கான நவீன மாற்றங்கள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Minister of Justice Outlines Comprehensive Modernization of Commercial Courts. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>වාණිජ මහාධිකරණ පද්ධතිය කඩිනම් නඩු විභාග සඳහා නවීකරණය කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>வணிக நீதிமன்ற கட்டமைப்பில் துரித வழக்கு விசாரணைக்கான நவீன மாற்றங்கள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8747, '2026-10-04 11:54:11', '2026-10-04 11:54:11', '2026-10-04 11:54:11', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 38, 'parliamentary-select-committee-on-energy-submits-clean-power-transition-roadmap', 'Parliamentary Select Committee on Energy Submits Clean Power Transition Roadmap', 'පුනර්ජනනීය බලශක්ති සංක්‍රාන්තිය පිළිබඳ පාර්ලිමේන්තු විශේෂ වාර්තාව සභාගත කෙරේ', 'புதுப்பிக்கத்தக்க சக்தி மாற்றத்திற்கான பாராளுமன்ற விசேட அறிக்கை சமர்ப்பிக்கப்பட்டது', 'Parliamentary Select Committee on Energy Submits Clean Power Transition Roadmap. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'පුනර්ජනනීය බලශක්ති සංක්‍රාන්තිය පිළිබඳ පාර්ලිමේන්තු විශේෂ වාර්තාව සභාගත කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'புதுப்பிக்கத்தக்க சக்தி மாற்றத்திற்கான பாராளுமன்ற விசேட அறிக்கை சமர்ப்பிக்கப்பட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Parliamentary Select Committee on Energy Submits Clean Power Transition Roadmap. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>පුනර්ජනනීය බලශක්ති සංක්‍රාන්තිය පිළිබඳ පාර්ලිමේන්තු විශේෂ වාර්තාව සභාගත කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>புதுப்பிக்கத்தக்க சக்தி மாற்றத்திற்கான பாராளுமன்ற விசேட அறிக்கை சமர்ப்பிக்கப்பட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 4170, '2026-10-04 09:03:32', '2026-10-04 09:03:32', '2026-10-04 09:03:32', '[39,40,41,42]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 2, 39, 'cabinet-sub-committee-approves-state-enterprise-restructuring-strategic-policy', 'Cabinet Sub-Committee Approves State Enterprise Restructuring Strategic Policy', 'රාජ්‍ය ව්‍යවසාය ප්‍රතිව්‍යුහගත කිරීමේ නව ක්‍රමෝපායික සැලැස්මට අනුමැතිය', 'அரச நிறுவனங்களை மறுசீரமைக்கும் புதிய மூலோபாய திட்டத்திற்கு அனுமதி', 'Cabinet Sub-Committee Approves State Enterprise Restructuring Strategic Policy. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'රාජ්‍ය ව්‍යවසාය ප්‍රතිව්‍යුහගත කිරීමේ නව ක්‍රමෝපායික සැලැස්මට අනුමැතිය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'அரச நிறுவனங்களை மறுசீரமைக்கும் புதிய மூலோபாய திட்டத்திற்கு அனுமதி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Cabinet Sub-Committee Approves State Enterprise Restructuring Strategic Policy. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>රාජ්‍ය ව්‍යවසාය ප්‍රතිව්‍යුහගත කිරීමේ නව ක්‍රමෝපායික සැලැස්මට අනුමැතිය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>அரச நிறுவனங்களை மறுசீரமைக்கும் புதிய மூலோபாய திட்டத்திற்கு அனுமதி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 3416, '2026-10-04 06:15:08', '2026-10-04 06:15:08', '2026-10-04 06:15:08', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 40, 'central-bank-retains-key-policy-rates-as-inflation-remains-firmly-in-single-digits', 'Central Bank Retains Key Policy Rates as Inflation Remains Firmly in Single Digits', 'උද්ධමනය පහළ අගයක පවතිද්දී මහ බැංකුව ප්‍රතිපත්ති පොලී අනුපාතික නොවෙනස්ව තබයි', 'பணவீக்கம் கட்டுப்பாட்டில் உள்ள நிலையில் மத்திய வங்கி கொள்கை வட்டி விகிதங்களை மாற்றமின்றி வைத்திருக்கிறது', 'Central Bank Retains Key Policy Rates as Inflation Remains Firmly in Single Digits. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'උද්ධමනය පහළ අගයක පවතිද්දී මහ බැංකුව ප්‍රතිපත්ති පොලී අනුපාතික නොවෙනස්ව තබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'பணவீக்கம் கட்டுப்பாட்டில் உள்ள நிலையில் மத்திய வங்கி கொள்கை வட்டி விகிதங்களை மாற்றமின்றி வைத்திருக்கிறது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Central Bank Retains Key Policy Rates as Inflation Remains Firmly in Single Digits. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>උද්ධමනය පහළ අගයක පවතිද්දී මහ බැංකුව ප්‍රතිපත්ති පොලී අනුපාතික නොවෙනස්ව තබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பணவீக்கம் கட்டுப்பாட்டில் உள்ள நிலையில் மத்திய வங்கி கொள்கை வட்டி விகிதங்களை மாற்றமின்றி வைத்திருக்கிறது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8090, '2026-10-04 02:55:07', '2026-10-04 02:55:07', '2026-10-04 02:55:07', '[]', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 41, 'colombo-stock-exchange-all-share-price-index-surges-past-13-000-milestone', 'Colombo Stock Exchange All Share Price Index Surges Past 13,000 Milestone', 'කොළඹ කොටස් වෙළෙඳපොළ සියලු කොටස් මිල දර්ශකය 13,000 සීමාව පසුකරයි', 'கொழும்பு பங்குச் சந்தை அனைத்துப் பங்கு விலைச் சுட்டெண் 13,000 புள்ளிகளை கடந்து சாதனை', 'Colombo Stock Exchange All Share Price Index Surges Past 13,000 Milestone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ කොටස් වෙළෙඳපොළ සියලු කොටස් මිල දර්ශකය 13,000 සීමාව පසුකරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு பங்குச் சந்தை அனைத்துப் பங்கு விலைச் சுட்டெண் 13,000 புள்ளிகளை கடந்து சாதனை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Colombo Stock Exchange All Share Price Index Surges Past 13,000 Milestone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ කොටස් වෙළෙඳපොළ සියලු කොටස් මිල දර්ශකය 13,000 සීමාව පසුකරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு பங்குச் சந்தை அனைத்துப் பங்கு விலைச் சுட்டெண் 13,000 புள்ளிகளை கடந்து சாதனை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8553, '2026-10-04 00:08:50', '2026-10-04 00:08:50', '2026-10-04 00:08:50', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 42, 'sri-lanka-export-development-board-reports-record-apparel-and-spices-revenue', 'Sri Lanka Export Development Board Reports Record Apparel and Spices Revenue', 'ඇඟලුම් සහ කුළුබඩු අපනයන ආදායම කැපී පෙනෙන ලෙස ඉහළ ගිය බව අපනයන මණ්ඩලය කියයි', 'ஆடை மற்றும் வாசனை திரவிய ஏற்றுமதி வருமானம் குறிப்பிடத்தக்க வளர்ச்சி என ஏற்றுமதி அபிவிருத்தி சபை தகவல்', 'Sri Lanka Export Development Board Reports Record Apparel and Spices Revenue. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ඇඟලුම් සහ කුළුබඩු අපනයන ආදායම කැපී පෙනෙන ලෙස ඉහළ ගිය බව අපනයන මණ්ඩලය කියයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஆடை மற்றும் வாசனை திரவிய ஏற்றுமதி வருமானம் குறிப்பிடத்தக்க வளர்ச்சி என ஏற்றுமதி அபிவிருத்தி சபை தகவல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Export Development Board Reports Record Apparel and Spices Revenue. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ඇඟලුම් සහ කුළුබඩු අපනයන ආදායම කැපී පෙනෙන ලෙස ඉහළ ගිය බව අපනයන මණ්ඩලය කියයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஆடை மற்றும் வாசனை திரவிய ஏற்றுமதி வருமானம் குறிப்பிடத்தக்க வளர்ச்சி என ஏற்றுமதி அபிவிருத்தி சபை தகவல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 1231, '2026-10-03 21:31:14', '2026-10-03 21:31:14', '2026-10-03 21:31:14', '[43,44,45,46]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 43, 'world-bank-approves-150-million-facility-to-strengthen-rural-msme-resilience', 'World Bank Approves $150 Million Facility to Strengthen Rural MSME Resilience', 'සුළු හා මධ්‍ය පරිමාණ ව්‍යාපාර නගාසිටුවීමට ලෝක බැංකුවෙන් ඩොලර් මිලියන 150 ක ණයක්', 'சிறு மற்றும் நடுத்தர தொழில்முயற்சிகளை மேம்படுத்த உலக வங்கி $150 மில்லியன் நிதி உதவி', 'World Bank Approves $150 Million Facility to Strengthen Rural MSME Resilience. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'සුළු හා මධ්‍ය පරිමාණ ව්‍යාපාර නගාසිටුවීමට ලෝක බැංකුවෙන් ඩොලර් මිලියන 150 ක ණයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சிறு மற்றும் நடுத்தர தொழில்முயற்சிகளை மேம்படுத்த உலக வங்கி $150 மில்லியன் நிதி உதவி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>World Bank Approves $150 Million Facility to Strengthen Rural MSME Resilience. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සුළු හා මධ්‍ය පරිමාණ ව්‍යාපාර නගාසිටුවීමට ලෝක බැංකුවෙන් ඩොලර් මිලියන 150 ක ණයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சிறு மற்றும் நடுத்தர தொழில்முயற்சிகளை மேம்படுத்த உலக வங்கி $150 மில்லியன் நிதி உதவி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 3995, '2026-10-03 18:56:40', '2026-10-03 18:56:40', '2026-10-03 18:56:40', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 44, 'commercial-banks-record-robust-growth-in-digital-qr-and-real-time-remittances', 'Commercial Banks Record Robust Growth in Digital QR and Real-Time Remittances', 'ඩිජිටල් මුදල් හුවමාරු සහ QR ගෙවීම් පද්ධතිය තුළ ඉහළ ප්‍රගතියක් වාර්තා වෙයි', 'டிஜிட்டல் பணப்பரிமாற்றம் மற்றும் QR கொடுப்பனவுகளில் பாரிய வளர்ச்சி பதிவு', 'Commercial Banks Record Robust Growth in Digital QR and Real-Time Remittances. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ඩිජිටල් මුදල් හුවමාරු සහ QR ගෙවීම් පද්ධතිය තුළ ඉහළ ප්‍රගතියක් වාර්තා වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'டிஜிட்டல் பணப்பரிமாற்றம் மற்றும் QR கொடுப்பனவுகளில் பாரிய வளர்ச்சி பதிவு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Commercial Banks Record Robust Growth in Digital QR and Real-Time Remittances. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ඩිජිටල් මුදල් හුවමාරු සහ QR ගෙවීම් පද්ධතිය තුළ ඉහළ ප්‍රගතියක් වාර්තා වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>டிஜிட்டல் பணப்பரிமாற்றம் மற்றும் QR கொடுப்பனவுகளில் பாரிய வளர்ச்சி பதிவு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5938, '2026-10-03 15:50:53', '2026-10-03 15:50:53', '2026-10-03 15:50:53', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 45, 'treasury-bill-yields-stabilize-amid-sustained-institutional-investor-demand', 'Treasury Bill Yields Stabilize Amid Sustained Institutional Investor Demand', 'භාණ්ඩාගාර බිල්පත් පොලී අනුපාත ස්ථාවර මට්ටමක පවතින බව මුදල් අමාත්‍යාංශය පවසයි', 'திறைசேரி உண்டியல் வட்டி விகிதங்கள் நிலையான தன்மையை எட்டியுள்ளன', 'Treasury Bill Yields Stabilize Amid Sustained Institutional Investor Demand. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'භාණ්ඩාගාර බිල්පත් පොලී අනුපාත ස්ථාවර මට්ටමක පවතින බව මුදල් අමාත්‍යාංශය පවසයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'திறைசேரி உண்டியல் வட்டி விகிதங்கள் நிலையான தன்மையை எட்டியுள்ளன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Treasury Bill Yields Stabilize Amid Sustained Institutional Investor Demand. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>භාණ්ඩාගාර බිල්පත් පොලී අනුපාත ස්ථාවර මට්ටමක පවතින බව මුදල් අමාත්‍යාංශය පවසයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>திறைசேரி உண்டியல் வட்டி விகிதங்கள் நிலையான தன்மையை எட்டியுள்ளன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 2846, '2026-10-03 12:47:19', '2026-10-03 12:47:19', '2026-10-03 12:47:19', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 46, 'tourism-development-authority-reports-surge-in-european-and-east-asian-arrivals', 'Tourism Development Authority Reports Surge in European and East Asian Arrivals', 'ශ්‍රී ලංකාවට පැමිණෙන විදේශීය සංචාරකයින්ගේ සංඛ්‍යාව ශීඝ්‍රයෙන් ඉහළට', 'இலங்கைக்கு வருகை தரும் வெளிநாட்டு சுற்றுலாப் பயணிகளின் எண்ணிக்கை அதிகரிப்பு', 'Tourism Development Authority Reports Surge in European and East Asian Arrivals. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ශ්‍රී ලංකාවට පැමිණෙන විදේශීය සංචාරකයින්ගේ සංඛ්‍යාව ශීඝ්‍රයෙන් ඉහළට. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கைக்கு வருகை தரும் வெளிநாட்டு சுற்றுலாப் பயணிகளின் எண்ணிக்கை அதிகரிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Tourism Development Authority Reports Surge in European and East Asian Arrivals. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ශ්‍රී ලංකාවට පැමිණෙන විදේශීය සංචාරකයින්ගේ සංඛ්‍යාව ශීඝ්‍රයෙන් ඉහළට. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கைக்கு வருகை தரும் வெளிநாட்டு சுற்றுலாப் பயணிகளின் எண்ணிக்கை அதிகரிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 3944, '2026-10-03 10:12:55', '2026-10-03 10:12:55', '2026-10-03 10:12:55', '[47,48,49,50]', 'https://www.youtube.com/watch?v=9bZkp7q19f0', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 47, 'port-city-colombo-welcomes-top-multinational-it-headquarters-into-business-zone', 'Port City Colombo Welcomes Top Multinational IT Headquarters into Business Zone', 'කොළඹ වරාය නගරයේ මූල්‍ය කලාපයට නව බහුජාතික තොරතුරු තාක්ෂණ සමාගම් එක්වෙයි', 'கொழும்பு துறைமுக நகரத்தில் புதிய பன்னாட்டு தகவல் தொழில்நுட்ப நிறுவனங்கள் ஆரம்பம்', 'Port City Colombo Welcomes Top Multinational IT Headquarters into Business Zone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ වරාය නගරයේ මූල්‍ය කලාපයට නව බහුජාතික තොරතුරු තාක්ෂණ සමාගම් එක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு துறைமுக நகரத்தில் புதிய பன்னாட்டு தகவல் தொழில்நுட்ப நிறுவனங்கள் ஆரம்பம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Port City Colombo Welcomes Top Multinational IT Headquarters into Business Zone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ වරාය නගරයේ මූල්‍ය කලාපයට නව බහුජාතික තොරතුරු තාක්ෂණ සමාගම් එක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு துறைமுக நகரத்தில் புதிய பன்னாட்டு தகவல் தொழில்நுட்ப நிறுவனங்கள் ஆரம்பம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9160, '2026-10-03 07:11:51', '2026-10-03 07:11:51', '2026-10-03 07:11:51', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 48, 'ceylon-petroleum-corporation-finalizes-long-term-fuel-security-storage-expansion', 'Ceylon Petroleum Corporation Finalizes Long-Term Fuel Security Storage Expansion', 'ඉන්ධන සුරක්ෂිතතාව වෙනුවෙන් ඛනිජ තෙල් සංස්ථාව නව ගබඩා සංකීර්ණ ඉදිකරයි', 'எரிபொருள் பாதுகாப்பை உறுதிப்படுத்த புதிய களஞ்சிய வசதிகள் விஸ்தரிப்பு', 'Ceylon Petroleum Corporation Finalizes Long-Term Fuel Security Storage Expansion. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ඉන්ධන සුරක්ෂිතතාව වෙනුවෙන් ඛනිජ තෙල් සංස්ථාව නව ගබඩා සංකීර්ණ ඉදිකරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'எரிபொருள் பாதுகாப்பை உறுதிப்படுத்த புதிய களஞ்சிய வசதிகள் விஸ்தரிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Ceylon Petroleum Corporation Finalizes Long-Term Fuel Security Storage Expansion. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ඉන්ධන සුරක්ෂිතතාව වෙනුවෙන් ඛනිජ තෙල් සංස්ථාව නව ගබඩා සංකීර්ණ ඉදිකරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>எரிபொருள் பாதுகாப்பை உறுதிப்படுத்த புதிய களஞ்சிய வசதிகள் விஸ்தரிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5843, '2026-10-03 04:36:09', '2026-10-03 04:36:09', '2026-10-03 04:36:09', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 49, 'national-tea-auctions-see-record-overseas-bidding-for-nuwara-eliya-pekoe', 'National Tea Auctions See Record Overseas Bidding for Nuwara Eliya Pekoe', 'කොළඹ තේ වෙන්දේසියේදී උසස් තත්ත්වයේ තේ සඳහා ඉහළ මිලක් හිමිවෙයි', 'கொழும்பு தேயிலை ஏலத்தில் உயர் ரக தேயிலைக்கு சர்வதேச ரீதியில் அதிகூடிய விலை', 'National Tea Auctions See Record Overseas Bidding for Nuwara Eliya Pekoe. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ තේ වෙන්දේසියේදී උසස් තත්ත්වයේ තේ සඳහා ඉහළ මිලක් හිමිවෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு தேயிலை ஏலத்தில் உயர் ரக தேயிலைக்கு சர்வதேச ரீதியில் அதிகூடிய விலை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Tea Auctions See Record Overseas Bidding for Nuwara Eliya Pekoe. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ තේ වෙන්දේසියේදී උසස් තත්ත්වයේ තේ සඳහා ඉහළ මිලක් හිමිවෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு தேயிலை ஏலத்தில் உயர் ரக தேயிலைக்கு சர்வதேச ரீதியில் அதிகூடிய விலை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5116, '2026-10-03 01:40:40', '2026-10-03 01:40:40', '2026-10-03 01:40:40', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 50, 'adb-backs-climate-resilient-agricultural-infrastructure-across-dry-zone', 'ADB Backs Climate-Resilient Agricultural Infrastructure Across Dry Zone', 'වියළි කලාපයේ කෘෂිකාර්මික ව්‍යාපෘති සඳහා ආසියානු සංවර්ධන බැංකුවෙන් ආධාර', 'உலர் வலய விவசாய அபிவிருத்தி திட்டங்களுக்கு ஆசிய அபிவிருத்தி வங்கி உதவி', 'ADB Backs Climate-Resilient Agricultural Infrastructure Across Dry Zone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'වියළි කලාපයේ කෘෂිකාර්මික ව්‍යාපෘති සඳහා ආසියානු සංවර්ධන බැංකුවෙන් ආධාර. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'உலர் வலய விவசாய அபிவிருத்தி திட்டங்களுக்கு ஆசிய அபிவிருத்தி வங்கி உதவி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>ADB Backs Climate-Resilient Agricultural Infrastructure Across Dry Zone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>වියළි කලාපයේ කෘෂිකාර්මික ව්‍යාපෘති සඳහා ආසියානු සංවර්ධන බැංකුවෙන් ආධාර. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>உலர் வலய விவசாய அபிவிருத்தி திட்டங்களுக்கு ஆசிய அபிவிருத்தி வங்கி உதவி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9299, '2026-10-02 22:25:23', '2026-10-02 22:25:23', '2026-10-02 22:25:23', '[51,52,53,54]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 51, 'sri-lanka-telecom-and-global-tech-giants-partner-on-new-subsea-fiber-route', 'Sri Lanka Telecom and Global Tech Giants Partner on New Subsea Fiber Route', 'නව සබ්මැරීන් සන්නිවේදන කේබල් පද්ධතියක් මෙරටට සම්බන්ධ කිරීමට ගිවිසුම්', 'புதிய கடலடி தொடர்பாடல் கேபிள் கட்டமைப்பை இணைக்க உடன்படிக்கை', 'Sri Lanka Telecom and Global Tech Giants Partner on New Subsea Fiber Route. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'නව සබ්මැරීන් සන්නිවේදන කේබල් පද්ධතියක් මෙරටට සම්බන්ධ කිරීමට ගිවිසුම්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'புதிய கடலடி தொடர்பாடல் கேபிள் கட்டமைப்பை இணைக்க உடன்படிக்கை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Telecom and Global Tech Giants Partner on New Subsea Fiber Route. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නව සබ්මැරීන් සන්නිවේදන කේබල් පද්ධතියක් මෙරටට සම්බන්ධ කිරීමට ගිවිසුම්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>புதிய கடலடி தொடர்பாடல் கேபிள் கட்டமைப்பை இணைக்க உடன்படிக்கை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6862, '2026-10-02 19:54:31', '2026-10-02 19:54:31', '2026-10-02 19:54:31', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 52, 'board-of-investment-signs-agreements-for-five-industrial-eco-parks', 'Board of Investment Signs Agreements for Five Industrial Eco-Parks', 'නව පරිසර හිතකාමී කර්මාන්ත ශාලා පහක් සඳහා ආයෝජන මණ්ඩලය ගිවිසුම් අත්සන් කරයි', 'புதிய சூழல் நட்பு தொழிற்சாலைகளுக்காக முதலீட்டு சபை ஒப்பந்தம்', 'Board of Investment Signs Agreements for Five Industrial Eco-Parks. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'නව පරිසර හිතකාමී කර්මාන්ත ශාලා පහක් සඳහා ආයෝජන මණ්ඩලය ගිවිසුම් අත්සන් කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'புதிய சூழல் நட்பு தொழிற்சாலைகளுக்காக முதலீட்டு சபை ஒப்பந்தம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Board of Investment Signs Agreements for Five Industrial Eco-Parks. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නව පරිසර හිතකාමී කර්මාන්ත ශාලා පහක් සඳහා ආයෝජන මණ්ඩලය ගිවිසුම් අත්සන් කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>புதிய சூழல் நட்பு தொழிற்சாலைகளுக்காக முதலீட்டு சபை ஒப்பந்தம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 9457, '2026-10-02 17:14:23', '2026-10-02 17:14:23', '2026-10-02 17:14:23', '[]', 'https://www.youtube.com/watch?v=kJQP7kiw5Fk', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 53, 'cinnamon-exporters-association-secures-enhanced-european-geographical-indication', 'Cinnamon Exporters Association Secures Enhanced European Geographical Indication', 'ලංකා කුරුඳු සඳහා යුරෝපා සංගමයේ භූගෝලීය දර්ශක සහතිකය හිමිවෙයි', 'இலங்கை கறுவாவுக்கு ஐரோப்பிய ஒன்றியத்தின் புவியியல் சார்ந்த குறியீடு அங்கீகாரம்', 'Cinnamon Exporters Association Secures Enhanced European Geographical Indication. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ලංකා කුරුඳු සඳහා යුරෝපා සංගමයේ භූගෝලීය දර්ශක සහතිකය හිමිවෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கை கறுவாவுக்கு ஐரோப்பிய ஒன்றியத்தின் புவியியல் சார்ந்த குறியீடு அங்கீகாரம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Cinnamon Exporters Association Secures Enhanced European Geographical Indication. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ලංකා කුරුඳු සඳහා යුරෝපා සංගමයේ භූගෝලීය දර්ශක සහතිකය හිමිවෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கை கறுவாவுக்கு ஐரோப்பிய ஒன்றியத்தின் புவியியல் சார்ந்த குறியீடு அங்கீகாரம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5379, '2026-10-02 14:15:38', '2026-10-02 14:15:38', '2026-10-02 14:15:38', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 3, 54, 'renewable-energy-independent-producers-connect-250mw-rooftop-solar-to-grid', 'Renewable Energy Independent Producers Connect 250MW Rooftop Solar to Grid', 'වහල මත සූර්ය පැනල මගින් මෙගාවොට් 250 ක බලශක්තියක් ජාතික පද්ධතියට එක්වෙයි', 'கூரை சூரிய மின்னுற்பத்தி மூலம் 250 மெகாவாட் மின்சாரம் தேசிய மின் கட்டமைப்பில் இணைப்பு', 'Renewable Energy Independent Producers Connect 250MW Rooftop Solar to Grid. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'වහල මත සූර්ය පැනල මගින් මෙගාවොට් 250 ක බලශක්තියක් ජාතික පද්ධතියට එක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கூரை சூரிய மின்னுற்பத்தி மூலம் 250 மெகாவாட் மின்சாரம் தேசிய மின் கட்டமைப்பில் இணைப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Renewable Energy Independent Producers Connect 250MW Rooftop Solar to Grid. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>වහල මත සූර්ය පැනල මගින් මෙගාවොට් 250 ක බලශක්තියක් ජාතික පද්ධතියට එක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கூரை சூரிய மின்னுற்பத்தி மூலம் 250 மெகாவாட் மின்சாரம் தேசிய மின் கட்டமைப்பில் இணைப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5390, '2026-10-02 11:14:56', '2026-10-02 11:14:56', '2026-10-02 11:14:56', '[55,56,57,58]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 55, 'sri-lanka-men-s-cricket-team-departs-for-high-stakes-multi-format-tour', 'Sri Lanka Men’s Cricket Team Departs for High-Stakes Multi-Format Tour', 'ශ්‍රී ලංකා ක්‍රිකට් කණ්ඩායම තීරණාත්මක විදෙස් තරග සංචාරයක් සඳහා පිටත්ව යයි', 'இலங்கை கிரிக்கெட் அணி தீர்க்கமான சர்வதேச கிரிக்கெட் தொடருக்காக புறப்பட்டது', 'Sri Lanka Men’s Cricket Team Departs for High-Stakes Multi-Format Tour. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ශ්‍රී ලංකා ක්‍රිකට් කණ්ඩායම තීරණාත්මක විදෙස් තරග සංචාරයක් සඳහා පිටත්ව යයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கை கிரிக்கெட் அணி தீர்க்கமான சர்வதேச கிரிக்கெட் தொடருக்காக புறப்பட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Men’s Cricket Team Departs for High-Stakes Multi-Format Tour. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ශ්‍රී ලංකා ක්‍රිකට් කණ්ඩායම තීරණාත්මක විදෙස් තරග සංචාරයක් සඳහා පිටත්ව යයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கை கிரிக்கெட் அணி தீர்க்கமான சர்வதேச கிரிக்கெட் தொடருக்காக புறப்பட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9399, '2026-10-02 08:52:44', '2026-10-02 08:52:44', '2026-10-02 08:52:44', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 56, 'pathum-nissanka-and-wanindu-hasaranga-climb-icc-world-rankings-following-victories', 'Pathum Nissanka and Wanindu Hasaranga Climb ICC World Rankings Following Victories', 'පැතුම් නිශ්ශංක සහ වනිඳු හසරංග අයි.සී.සී. ශ්‍රේණිගත කිරීම්වල ඉදිරියට පැමිණෙයි', 'பெதும் நிஸ்ஸங்க மற்றும் வனிந்து ஹசரங்க ஐசிசி தரவரிசையில் முன்னேற்றம்', 'Pathum Nissanka and Wanindu Hasaranga Climb ICC World Rankings Following Victories. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'පැතුම් නිශ්ශංක සහ වනිඳු හසරංග අයි.සී.සී. ශ්‍රේණිගත කිරීම්වල ඉදිරියට පැමිණෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'பெதும் நிஸ்ஸங்க மற்றும் வனிந்து ஹசரங்க ஐசிசி தரவரிசையில் முன்னேற்றம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Pathum Nissanka and Wanindu Hasaranga Climb ICC World Rankings Following Victories. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>පැතුම් නිශ්ශංක සහ වනිඳු හසරංග අයි.සී.සී. ශ්‍රේණිගත කිරීම්වල ඉදිරියට පැමිණෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பெதும் நிஸ்ஸங்க மற்றும் வனிந்து ஹசரங்க ஐசிசி தரவரிசையில் முன்னேற்றம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5885, '2026-10-02 05:45:44', '2026-10-02 05:45:44', '2026-10-02 05:45:44', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 57, 'national-athletic-championship-sprinters-break-national-records-at-sugathadasa', 'National Athletic Championship: Sprinters Break National Records at Sugathadasa', 'සුගතදාස ක්‍රීඩාංගණයේදී ජාතික කෙටිදුර ධාවන වාර්තා කිහිපයක් බිඳවැටෙයි', 'சுகததாச அரங்கில் தேசிய குறுந்தூர ஓட்டப் போட்டிகளில் புதிய சாதனைகள் நிலைநாட்டப்பட்டன', 'National Athletic Championship: Sprinters Break National Records at Sugathadasa. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'සුගතදාස ක්‍රීඩාංගණයේදී ජාතික කෙටිදුර ධාවන වාර්තා කිහිපයක් බිඳවැටෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சுகததாச அரங்கில் தேசிய குறுந்தூர ஓட்டப் போட்டிகளில் புதிய சாதனைகள் நிலைநாட்டப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Athletic Championship: Sprinters Break National Records at Sugathadasa. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සුගතදාස ක්‍රීඩාංගණයේදී ජාතික කෙටිදුර ධාවන වාර්තා කිහිපයක් බිඳවැටෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சுகததாச அரங்கில் தேசிய குறுந்தூர ஓட்டப் போட்டிகளில் புதிய சாதனைகள் நிலைநாட்டப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8757, '2026-10-02 02:41:27', '2026-10-02 02:41:27', '2026-10-02 02:41:27', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 58, 'chamari-athapaththu-leads-sri-lanka-women-s-cricket-to-historic-odi-series-sweep', 'Chamari Athapaththu Leads Sri Lanka Women’s Cricket to Historic ODI Series Sweep', 'චමරි අතපත්තුගේ නායකත්වයෙන් යුත් ශ්‍රී ලංකා කාන්තා කණ්ඩායම ඓතිහාසික ජයක් ලබයි', 'சமரி அதபத்து தலைமையிலான இலங்கை மகளிர் அணி வரலாற்று வெற்றியை பதிவு செய்தது', 'Chamari Athapaththu Leads Sri Lanka Women’s Cricket to Historic ODI Series Sweep. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'චමරි අතපත්තුගේ නායකත්වයෙන් යුත් ශ්‍රී ලංකා කාන්තා කණ්ඩායම ඓතිහාසික ජයක් ලබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சமரி அதபத்து தலைமையிலான இலங்கை மகளிர் அணி வரலாற்று வெற்றியை பதிவு செய்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Chamari Athapaththu Leads Sri Lanka Women’s Cricket to Historic ODI Series Sweep. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>චමරි අතපත්තුගේ නායකත්වයෙන් යුත් ශ්‍රී ලංකා කාන්තා කණ්ඩායම ඓතිහාසික ජයක් ලබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சமரி அதபத்து தலைமையிலான இலங்கை மகளிர் அணி வரலாற்று வெற்றியை பதிவு செய்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 9441, '2026-10-02 00:03:17', '2026-10-02 00:03:17', '2026-10-02 00:03:17', '[59,60,61,62]', 'https://www.youtube.com/watch?v=fJ9rUzIMcZQ', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 59, 'inter-school-rugby-league-royal-and-trinity-set-up-thrilling-bradby-shield-clash', 'Inter-School Rugby League: Royal and Trinity Set Up Thrilling Bradby Shield Clash', 'බ්‍රැඩ්බි පළිහ රගර් තරගාවලියේ පළමු අදියර උණුසුම් මුහුණුවරක් ගනී', 'பிராட்பி கேடய ரக்பி போட்டியின் முதலாவது சுற்று விறுவிறுப்பாக ஆரம்பம்', 'Inter-School Rugby League: Royal and Trinity Set Up Thrilling Bradby Shield Clash. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'බ්‍රැඩ්බි පළිහ රගර් තරගාවලියේ පළමු අදියර උණුසුම් මුහුණුවරක් ගනී. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'பிராட்பி கேடய ரக்பி போட்டியின் முதலாவது சுற்று விறுவிறுப்பாக ஆரம்பம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Inter-School Rugby League: Royal and Trinity Set Up Thrilling Bradby Shield Clash. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>බ්‍රැඩ්බි පළිහ රගර් තරගාවලියේ පළමු අදියර උණුසුම් මුහුණුවරක් ගනී. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பிராட்பி கேடய ரக்பி போட்டியின் முதலாவது சுற்று விறுவிறுப்பாக ஆரம்பம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 9201, '2026-10-01 20:53:46', '2026-10-01 20:53:46', '2026-10-01 20:53:46', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 60, 'sri-lanka-badminton-open-welcomes-world-champions-to-colombo-indoor-stadium', 'Sri Lanka Badminton Open Welcomes World Champions to Colombo Indoor Stadium', 'කොළඹදී ඇරඹෙන ජාත්‍යන්තර බැඩ්මින්ටන් තරගාවලියට ලෝක ශූරයින් එක්වෙයි', 'கொழும்பில் நடைபெறும் சர்வதேச இறகுப்பந்து தொடரில் உலக சாம்பியன்கள் பங்கேற்பு', 'Sri Lanka Badminton Open Welcomes World Champions to Colombo Indoor Stadium. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹදී ඇරඹෙන ජාත්‍යන්තර බැඩ්මින්ටන් තරගාවලියට ලෝක ශූරයින් එක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பில் நடைபெறும் சர்வதேச இறகுப்பந்து தொடரில் உலக சாம்பியன்கள் பங்கேற்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Badminton Open Welcomes World Champions to Colombo Indoor Stadium. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹදී ඇරඹෙන ජාත්‍යන්තර බැඩ්මින්ටන් තරගාවලියට ලෝක ශූරයින් එක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பில் நடைபெறும் சர்வதேச இறகுப்பந்து தொடரில் உலக சாம்பியன்கள் பங்கேற்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 7087, '2026-10-01 18:23:51', '2026-10-01 18:23:51', '2026-10-01 18:23:51', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 61, 'lanka-premier-league-announces-player-draft-dates-and-franchise-expansions', 'Lanka Premier League Announces Player Draft Dates and Franchise Expansions', 'ලංකා ප්‍රිමියර් ලීග් ක්‍රිකට් තරගාවලියේ නව කණ්ඩායම් සහ ක්‍රීඩක කෙටුම්පත් දින ප්‍රකාශයට පත්කෙරේ', 'லங்கா பிரீமியர் லீக் தொடரின் புதிய அணிகள் மற்றும் வீரர்கள் தெரிவு விபரங்கள் வெளியீடு', 'Lanka Premier League Announces Player Draft Dates and Franchise Expansions. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ලංකා ප්‍රිමියර් ලීග් ක්‍රිකට් තරගාවලියේ නව කණ්ඩායම් සහ ක්‍රීඩක කෙටුම්පත් දින ප්‍රකාශයට පත්කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'லங்கா பிரீமியர் லீக் தொடரின் புதிய அணிகள் மற்றும் வீரர்கள் தெரிவு விபரங்கள் வெளியீடு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Lanka Premier League Announces Player Draft Dates and Franchise Expansions. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ලංකා ප්‍රිමියර් ලීග් ක්‍රිකට් තරගාවලියේ නව කණ්ඩායම් සහ ක්‍රීඩක කෙටුම්පත් දින ප්‍රකාශයට පත්කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>லங்கா பிரீமியர் லீக் தொடரின் புதிய அணிகள் மற்றும் வீரர்கள் தெரிவு விபரங்கள் வெளியீடு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8298, '2026-10-01 15:56:45', '2026-10-01 15:56:45', '2026-10-01 15:56:45', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 62, 'south-asian-games-trials-national-swimming-squad-clocks-olympic-standard-times', 'South Asian Games Trials: National Swimming Squad Clocks Olympic Standard Times', 'දකුණු ආසියානු ක්‍රීඩා උළෙල වෙනුවෙන් පැවති පිහිනුම් තේරීම් තරගවලදී විශිෂ්ට දක්ෂතා', 'தெற்காசிய விளையாட்டு போட்டிக்கான நீச்சல் தகுதிச் சுற்றில் இலங்கை வீரர்கள் அசத்தல்', 'South Asian Games Trials: National Swimming Squad Clocks Olympic Standard Times. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'දකුණු ආසියානු ක්‍රීඩා උළෙල වෙනුවෙන් පැවති පිහිනුම් තේරීම් තරගවලදී විශිෂ්ට දක්ෂතා. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'தெற்காசிய விளையாட்டு போட்டிக்கான நீச்சல் தகுதிச் சுற்றில் இலங்கை வீரர்கள் அசத்தல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>South Asian Games Trials: National Swimming Squad Clocks Olympic Standard Times. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දකුණු ආසියානු ක්‍රීඩා උළෙල වෙනුවෙන් පැවති පිහිනුම් තේරීම් තරගවලදී විශිෂ්ට දක්ෂතා. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தெற்காசிய விளையாட்டு போட்டிக்கான நீச்சல் தகுதிச் சுற்றில் இலங்கை வீரர்கள் அசத்தல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 7945, '2026-10-01 13:10:28', '2026-10-01 13:10:28', '2026-10-01 13:10:28', '[63,64,65,66]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 63, 'sri-lanka-volleyball-federation-launches-island-wide-youth-development-trophy', 'Sri Lanka Volleyball Federation Launches Island-Wide Youth Development Trophy', 'දිවයින පුරා පාසල් වොලිබෝල් ක්‍රීඩකයින් වෙනුවෙන් නව තරගාවලියක්', 'நாடளாவிய ரீதியில் பாடசாலை கரப்பந்து வீரர்களுக்கான புதிய போட்டித் தொடர் ஆரம்பம்', 'Sri Lanka Volleyball Federation Launches Island-Wide Youth Development Trophy. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'දිවයින පුරා පාසල් වොලිබෝල් ක්‍රීඩකයින් වෙනුවෙන් නව තරගාවලියක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'நாடளாவிய ரீதியில் பாடசாலை கரப்பந்து வீரர்களுக்கான புதிய போட்டித் தொடர் ஆரம்பம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Volleyball Federation Launches Island-Wide Youth Development Trophy. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දිවයින පුරා පාසල් වොලිබෝල් ක්‍රීඩකයින් වෙනුවෙන් නව තරගාවලියක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>நாடளாவிய ரீதியில் பாடசாலை கரப்பந்து வீரர்களுக்கான புதிய போட்டித் தொடர் ஆரம்பம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2450, '2026-10-01 10:04:17', '2026-10-01 10:04:17', '2026-10-01 10:04:17', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 64, 'asian-table-tennis-championship-sri-lankan-doubles-pair-advances-to-quarter-finals', 'Asian Table Tennis Championship: Sri Lankan Doubles Pair Advances to Quarter-Finals', 'ආසියානු මේසපන්දු තරගාවලියේ අර්ධ අවසන් පූර්ව වටයට ශ්‍රී ලංකා යුගලය සුදුසුකම් ලබයි', 'ஆசிய மேசைப்பந்து தொடரின் காலிறுதிச் சுற்றுக்கு இலங்கை இணை முன்னேறியது', 'Asian Table Tennis Championship: Sri Lankan Doubles Pair Advances to Quarter-Finals. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ආසියානු මේසපන්දු තරගාවලියේ අර්ධ අවසන් පූර්ව වටයට ශ්‍රී ලංකා යුගලය සුදුසුකම් ලබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஆசிய மேசைப்பந்து தொடரின் காலிறுதிச் சுற்றுக்கு இலங்கை இணை முன்னேறியது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Asian Table Tennis Championship: Sri Lankan Doubles Pair Advances to Quarter-Finals. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ආසියානු මේසපන්දු තරගාවලියේ අර්ධ අවසන් පූර්ව වටයට ශ්‍රී ලංකා යුගලය සුදුසුකම් ලබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஆசிய மேசைப்பந்து தொடரின் காலிறுதிச் சுற்றுக்கு இலங்கை இணை முன்னேறியது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8144, '2026-10-01 07:11:22', '2026-10-01 07:11:22', '2026-10-01 07:11:22', '[]', 'https://www.youtube.com/watch?v=kXYiU_JCYtU', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 65, 'international-marathon-across-scenic-ella-draws-over-3-000-global-runners', 'International Marathon Across Scenic Ella Draws Over 3,000 Global Runners', 'ඇල්ල ප්‍රදේශයේ පැවති ජාත්‍යන්තර මැරතන් තරගයට දෙස් විදෙස් ක්‍රීඩක ක්‍රීඩිකාවන් 3,000 ක්', 'எல்ல பகுதியில் நடைபெற்ற சர்வதேச மரதன் ஓட்டத்தில் 3,000 க்கும் மேற்பட்ட வீரர்கள் பங்கேற்பு', 'International Marathon Across Scenic Ella Draws Over 3,000 Global Runners. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ඇල්ල ප්‍රදේශයේ පැවති ජාත්‍යන්තර මැරතන් තරගයට දෙස් විදෙස් ක්‍රීඩක ක්‍රීඩිකාවන් 3,000 ක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'எல்ல பகுதியில் நடைபெற்ற சர்வதேச மரதன் ஓட்டத்தில் 3,000 க்கும் மேற்பட்ட வீரர்கள் பங்கேற்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>International Marathon Across Scenic Ella Draws Over 3,000 Global Runners. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ඇල්ල ප්‍රදේශයේ පැවති ජාත්‍යන්තර මැරතන් තරගයට දෙස් විදෙස් ක්‍රීඩක ක්‍රීඩිකාවන් 3,000 ක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>எல்ல பகுதியில் நடைபெற்ற சர்வதேச மரதன் ஓட்டத்தில் 3,000 க்கும் மேற்பட்ட வீரர்கள் பங்கேற்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5292, '2026-10-01 04:31:25', '2026-10-01 04:31:25', '2026-10-01 04:31:25', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 66, 'slc-high-performance-center-at-khettarama-unveils-advanced-biomechanics-lab', 'SLC High Performance Center at Khettarama Unveils Advanced Biomechanics Lab', 'ඛෙත්තාරාම ක්‍රිකට් මධ්‍යස්ථානයේ නවීන ජෛව යාන්ත්‍රික විද්‍යාගාරයක් විවෘත වෙයි', 'கெத்தாராம கிரிக்கெட் பயிற்சி மையத்தில் அதிநவீன ஆய்வுகூடம் திறப்பு', 'SLC High Performance Center at Khettarama Unveils Advanced Biomechanics Lab. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ඛෙත්තාරාම ක්‍රිකට් මධ්‍යස්ථානයේ නවීන ජෛව යාන්ත්‍රික විද්‍යාගාරයක් විවෘත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கெத்தாராம கிரிக்கெட் பயிற்சி மையத்தில் அதிநவீன ஆய்வுகூடம் திறப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>SLC High Performance Center at Khettarama Unveils Advanced Biomechanics Lab. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ඛෙත්තාරාම ක්‍රිකට් මධ්‍යස්ථානයේ නවීන ජෛව යාන්ත්‍රික විද්‍යාගාරයක් විවෘත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கெத்தாராம கிரிக்கெட் பயிற்சி மையத்தில் அதிநவீன ஆய்வுகூடம் திறப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 5603, '2026-10-01 01:24:52', '2026-10-01 01:24:52', '2026-10-01 01:24:52', '[67,68,69,70]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 67, 'national-football-league-resumes-with-sold-out-crowds-in-colombo-and-jaffna', 'National Football League Resumes with Sold-Out Crowds in Colombo and Jaffna', 'කොළඹ සහ යාපනයේ ක්‍රීඩාංගණ පිරී ඉතිරී යමින් ජාතික පාපන්දු තරගාවලිය ඇරඹෙයි', 'கொழும்பு மற்றும் யாழ்ப்பாணத்தில் இரசிகர்களின் பெரும் ஆதரவுடன் தேசிய உதைபந்தாட்ட தொடர்', 'National Football League Resumes with Sold-Out Crowds in Colombo and Jaffna. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ සහ යාපනයේ ක්‍රීඩාංගණ පිරී ඉතිරී යමින් ජාතික පාපන්දු තරගාවලිය ඇරඹෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு மற்றும் யாழ்ப்பாணத்தில் இரசிகர்களின் பெரும் ஆதரவுடன் தேசிய உதைபந்தாட்ட தொடர். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Football League Resumes with Sold-Out Crowds in Colombo and Jaffna. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ සහ යාපනයේ ක්‍රීඩාංගණ පිරී ඉතිරී යමින් ජාතික පාපන්දු තරගාවලිය ඇරඹෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு மற்றும் யாழ்ப்பாணத்தில் இரசிகர்களின் பெரும் ஆதரவுடன் தேசிய உதைபந்தாட்ட தொடர். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 9650, '2026-09-30 22:25:15', '2026-09-30 22:25:15', '2026-09-30 22:25:15', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 68, 'world-chess-federation-recognizes-young-sri-lankan-prodigy-as-grandmaster', 'World Chess Federation Recognizes Young Sri Lankan Prodigy as Grandmaster', 'ශ්‍රී ලාංකික යොවුන් චෙස් ක්‍රීඩකයෙකු ජාත්‍යන්තර ග්‍රෑන්ඩ්මාස්ටර් සම්මානය දිනාගනී', 'இலங்கையின் இளம் சதுரங்க வீரர் சர்வதேச கிராண்ட்மாஸ்டர் பட்டத்தை வென்றார்', 'World Chess Federation Recognizes Young Sri Lankan Prodigy as Grandmaster. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ශ්‍රී ලාංකික යොවුන් චෙස් ක්‍රීඩකයෙකු ජාත්‍යන්තර ග්‍රෑන්ඩ්මාස්ටර් සම්මානය දිනාගනී. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கையின் இளம் சதுரங்க வீரர் சர்வதேச கிராண்ட்மாஸ்டர் பட்டத்தை வென்றார். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>World Chess Federation Recognizes Young Sri Lankan Prodigy as Grandmaster. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ශ්‍රී ලාංකික යොවුන් චෙස් ක්‍රීඩකයෙකු ජාත්‍යන්තර ග්‍රෑන්ඩ්මාස්ටර් සම්මානය දිනාගනී. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கையின் இளம் சதுரங்க வீரர் சர்வதேச கிராண்ட்மாஸ்டர் பட்டத்தை வென்றார். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2164, '2026-09-30 20:04:41', '2026-09-30 20:04:41', '2026-09-30 20:04:41', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 4, 69, 'sri-lanka-rowing-crew-wins-gold-at-asian-masters-regatta-in-hong-kong', 'Sri Lanka Rowing Crew Wins Gold at Asian Masters Regatta in Hong Kong', 'හොංකොං හි පැවති ආසියානු ඔරු පැදීමේ තරගාවලියෙන් ශ්‍රී ලංකාවට රන් පදක්කමක්', 'ஹொங்கொங்கில் நடைபெற்ற ஆசிய படகோட்ட போட்டியில் இலங்கைக்கு தங்கப் பதக்கம்', 'Sri Lanka Rowing Crew Wins Gold at Asian Masters Regatta in Hong Kong. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'හොංකොං හි පැවති ආසියානු ඔරු පැදීමේ තරගාවලියෙන් ශ්‍රී ලංකාවට රන් පදක්කමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஹொங்கொங்கில் நடைபெற்ற ஆசிய படகோட்ட போட்டியில் இலங்கைக்கு தங்கப் பதக்கம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Rowing Crew Wins Gold at Asian Masters Regatta in Hong Kong. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>හොංකොං හි පැවති ආසියානු ඔරු පැදීමේ තරගාවලියෙන් ශ්‍රී ලංකාවට රන් පදක්කමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஹொங்கொங்கில் நடைபெற்ற ஆசிய படகோட்ட போட்டியில் இலங்கைக்கு தங்கப் பதக்கம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 4977, '2026-09-30 17:11:03', '2026-09-30 17:11:03', '2026-09-30 17:11:03', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 70, 'derana-cinema-awards-celebrates-golden-era-of-sri-lankan-cinematic-storytelling', 'Derana Cinema Awards Celebrates Golden Era of Sri Lankan Cinematic Storytelling', 'දෙරණ සිනමා සම්මාන උළෙලේදී විශිෂ්ටතම සිනමා නිර්මාණ ඇගයීමට ලක්වෙයි', 'தெரண சினிமா விருது விழாவில் சிறந்த திரைப்பட படைப்பாளிகள் கௌரவிக்கப்பட்டனர்', 'Derana Cinema Awards Celebrates Golden Era of Sri Lankan Cinematic Storytelling. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'දෙරණ සිනමා සම්මාන උළෙලේදී විශිෂ්ටතම සිනමා නිර්මාණ ඇගයීමට ලක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'தெரண சினிமா விருது விழாவில் சிறந்த திரைப்பட படைப்பாளிகள் கௌரவிக்கப்பட்டனர். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Derana Cinema Awards Celebrates Golden Era of Sri Lankan Cinematic Storytelling. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දෙරණ සිනමා සම්මාන උළෙලේදී විශිෂ්ටතම සිනමා නිර්මාණ ඇගයීමට ලක්වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தெரண சினிமா விருது விழாவில் சிறந்த திரைப்பட படைப்பாளிகள் கௌரவிக்கப்பட்டனர். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 6288, '2026-09-30 13:58:09', '2026-09-30 13:58:09', '2026-09-30 13:58:09', '[71,72,73,74]', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 71, 'renowned-sri-lankan-filmmaker-s-indie-masterpiece-wins-best-feature-at-cannes', 'Renowned Sri Lankan Filmmaker’s Indie Masterpiece Wins Best Feature at Cannes', 'කෑන්ස් ජාත්‍යන්තර සිනමා උළෙලේදී ශ්‍රී ලාංකික සිනමා පටයකට විශේෂ ඇගයීමක්', 'கான் சர்வதேச திரைப்பட விழாவில் இலங்கை இயக்குனரின் படைப்புக்கு சர்வதேச விருது', 'Renowned Sri Lankan Filmmaker’s Indie Masterpiece Wins Best Feature at Cannes. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කෑන්ස් ජාත්‍යන්තර සිනමා උළෙලේදී ශ්‍රී ලාංකික සිනමා පටයකට විශේෂ ඇගයීමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கான் சர்வதேச திரைப்பட விழாவில் இலங்கை இயக்குனரின் படைப்புக்கு சர்வதேச விருது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Renowned Sri Lankan Filmmaker’s Indie Masterpiece Wins Best Feature at Cannes. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කෑන්ස් ජාත්‍යන්තර සිනමා උළෙලේදී ශ්‍රී ලාංකික සිනමා පටයකට විශේෂ ඇගයීමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கான் சர்வதேச திரைப்பட விழாவில் இலங்கை இயக்குனரின் படைப்புக்கு சர்வதேச விருது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 866, '2026-09-30 11:18:17', '2026-09-30 11:18:17', '2026-09-30 11:18:17', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 72, 'historic-lionel-wendt-theatre-stages-acclaimed-revival-of-sinhala-theatre-classic', 'Historic Lionel Wendt Theatre Stages Acclaimed Revival of Sinhala Theatre Classic', 'ලයනල් වෙන්ඩ්ට් රඟහලේදී සම්භාව්‍ය නාට්‍ය ප්‍රසංගයක් වේදිකාගත කෙරේ', 'லயனல் வெண்ட் கலையரங்கில் வரலாற்று சிறப்புமிக்க நாடக படைப்பு மேடையேறியது', 'Historic Lionel Wendt Theatre Stages Acclaimed Revival of Sinhala Theatre Classic. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ලයනල් වෙන්ඩ්ට් රඟහලේදී සම්භාව්‍ය නාට්‍ය ප්‍රසංගයක් වේදිකාගත කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'லயனல் வெண்ட் கலையரங்கில் வரலாற்று சிறப்புமிக்க நாடக படைப்பு மேடையேறியது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Historic Lionel Wendt Theatre Stages Acclaimed Revival of Sinhala Theatre Classic. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ලයනල් වෙන්ඩ්ට් රඟහලේදී සම්භාව්‍ය නාට්‍ය ප්‍රසංගයක් වේදිකාගත කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>லயனல் வெண்ட் கலையரங்கில் வரலாற்று சிறப்புமிக்க நாடக படைப்பு மேடையேறியது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2310, '2026-09-30 07:57:02', '2026-09-30 07:57:02', '2026-09-30 07:57:02', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 73, 'colombo-international-book-fair-draws-over-1-million-visitors-to-bmich', 'Colombo International Book Fair Draws Over 1 Million Visitors to BMICH', 'කොළඹ ජාත්‍යන්තර පොත් ප්‍රදර්ශනය සාර්ථකව අවසන් වෙයි', 'கொழும்பு சர்வதேச புத்தகக் கண்காட்சி வெற்றிகரமாக நிறைவு பெற்றது', 'Colombo International Book Fair Draws Over 1 Million Visitors to BMICH. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ ජාත්‍යන්තර පොත් ප්‍රදර්ශනය සාර්ථකව අවසන් වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு சர்வதேச புத்தகக் கண்காட்சி வெற்றிகரமாக நிறைவு பெற்றது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Colombo International Book Fair Draws Over 1 Million Visitors to BMICH. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ ජාත්‍යන්තර පොත් ප්‍රදර්ශනය සාර්ථකව අවසන් වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு சர்வதேச புத்தகக் கண்காட்சி வெற்றிகரமாக நிறைவு பெற்றது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 6786, '2026-09-30 05:45:41', '2026-09-30 05:45:41', '2026-09-30 05:45:41', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 74, 'galle-literary-festival-announces-star-studded-international-author-lineup', 'Galle Literary Festival Announces Star-Studded International Author Lineup', 'ගාල්ල සාහිත්‍ය උළෙල සඳහා ලොව ප්‍රමුඛ කතුවරුන් රැසක් දිවයිනට', 'காலி இலக்கிய விழாவிற்கு சர்வதேச எழுத்தாளர்கள் பலர் வருகை', 'Galle Literary Festival Announces Star-Studded International Author Lineup. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ගාල්ල සාහිත්‍ය උළෙල සඳහා ලොව ප්‍රමුඛ කතුවරුන් රැසක් දිවයිනට. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'காலி இலக்கிய விழாவிற்கு சர்வதேச எழுத்தாளர்கள் பலர் வருகை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Galle Literary Festival Announces Star-Studded International Author Lineup. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ගාල්ල සාහිත්‍ය උළෙල සඳහා ලොව ප්‍රමුඛ කතුවරුන් රැසක් දිවයිනට. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>காலி இலக்கிய விழாவிற்கு சர்வதேச எழுத்தாளர்கள் பலர் வருகை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8727, '2026-09-30 02:38:24', '2026-09-30 02:38:24', '2026-09-30 02:38:24', '[75,76,77,78]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 75, 'sensational-acoustic-music-festival-lights-up-viharamahadevi-amphitheatre', 'Sensational Acoustic Music Festival Lights Up Viharamahadevi Amphitheatre', 'විහාරමහාදේවි එළිමහන් රඟහලේදී අති උත්කර්ෂවත් සංගීත සැඳෑවක්', 'விஹாரமஹாதேவி திறந்தவெளி அரங்கில் கோலாகலமான இசை நிகழ்ச்சி', 'Sensational Acoustic Music Festival Lights Up Viharamahadevi Amphitheatre. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'විහාරමහාදේවි එළිමහන් රඟහලේදී අති උත්කර්ෂවත් සංගීත සැඳෑවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'விஹாரமஹாதேவி திறந்தவெளி அரங்கில் கோலாகலமான இசை நிகழ்ச்சி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sensational Acoustic Music Festival Lights Up Viharamahadevi Amphitheatre. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>විහාරමහාදේවි එළිමහන් රඟහලේදී අති උත්කර්ෂවත් සංගීත සැඳෑවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>விஹாரமஹாதேவி திறந்தவெளி அரங்கில் கோலாகலமான இசை நிகழ்ச்சி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 4658, '2026-09-29 23:56:20', '2026-09-29 23:56:20', '2026-09-29 23:56:20', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 76, 'national-youth-orchestra-delivers-spellbinding-symphony-at-nelum-pokuna-theatre', 'National Youth Orchestra Delivers Spellbinding Symphony at Nelum Pokuna Theatre', 'නෙළුම් පොකුණ රඟහලේදී ජාතික යොවුන් වාද්‍ය වෘන්දයේ සංධ්වනි ප්‍රසංගය', 'தாமரை தடாகம் அரங்கில் தேசிய இளைஞர் இசைக்குழுவின் கம்பீரமான இசை நிகழ்ச்சி', 'National Youth Orchestra Delivers Spellbinding Symphony at Nelum Pokuna Theatre. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'නෙළුම් පොකුණ රඟහලේදී ජාතික යොවුන් වාද්‍ය වෘන්දයේ සංධ්වනි ප්‍රසංගය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'தாமரை தடாகம் அரங்கில் தேசிய இளைஞர் இசைக்குழுவின் கம்பீரமான இசை நிகழ்ச்சி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Youth Orchestra Delivers Spellbinding Symphony at Nelum Pokuna Theatre. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නෙළුම් පොකුණ රඟහලේදී ජාතික යොවුන් වාද්‍ය වෘන්දයේ සංධ්වනි ප්‍රසංගය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தாமரை தடாகம் அரங்கில் தேசிய இளைஞர் இசைக்குழுவின் கம்பீரமான இசை நிகழ்ச்சி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6923, '2026-09-29 20:51:05', '2026-09-29 20:51:05', '2026-09-29 20:51:05', '[]', 'https://www.youtube.com/watch?v=9bZkp7q19f0', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 77, 'blockbuster-superhero-cinematic-sequel-shatters-sri-lankan-box-office-records', 'Blockbuster Superhero Cinematic Sequel Shatters Sri Lankan Box Office Records', 'මෙරට සිනමා ශාලා තුළ නවතම හොලිවුඩ් චිත්‍රපටය ඉහළම ආදායම් වාර්තාවක් පිහිටුවයි', 'இலங்கை திரையரங்குகளில் புதிய ஹொலிவுட் திரைப்படம் வசூல் சாதனை படைத்தது', 'Blockbuster Superhero Cinematic Sequel Shatters Sri Lankan Box Office Records. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මෙරට සිනමා ශාලා තුළ නවතම හොලිවුඩ් චිත්‍රපටය ඉහළම ආදායම් වාර්තාවක් පිහිටුවයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கை திரையரங்குகளில் புதிய ஹொலிவுட் திரைப்படம் வசூல் சாதனை படைத்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Blockbuster Superhero Cinematic Sequel Shatters Sri Lankan Box Office Records. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මෙරට සිනමා ශාලා තුළ නවතම හොලිවුඩ් චිත්‍රපටය ඉහළම ආදායම් වාර්තාවක් පිහිටුවයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கை திரையரங்குகளில் புதிய ஹொலிவுட் திரைப்படம் வசூல் சாதனை படைத்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 1100, '2026-09-29 18:40:11', '2026-09-29 18:40:11', '2026-09-29 18:40:11', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 78, 'national-art-gallery-opens-comprehensive-retrospective-of-43-group-modernists', 'National Art Gallery Opens Comprehensive Retrospective of 43 Group Modernists', 'ජාතික කලාභවනේදී ඓතිහාසික චිත්‍ර හා මූර්ති ප්‍රදර්ශනයක් විවෘත වෙයි', 'தேசிய கலைக்கூடத்தில் வரலாற்று சிறப்புமிக்க ஓவிய மற்றும் சிற்ப கண்காட்சி', 'National Art Gallery Opens Comprehensive Retrospective of 43 Group Modernists. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ජාතික කලාභවනේදී ඓතිහාසික චිත්‍ර හා මූර්ති ප්‍රදර්ශනයක් විවෘත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'தேசிய கலைக்கூடத்தில் வரலாற்று சிறப்புமிக்க ஓவிய மற்றும் சிற்ப கண்காட்சி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Art Gallery Opens Comprehensive Retrospective of 43 Group Modernists. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ජාතික කලාභවනේදී ඓතිහාසික චිත්‍ර හා මූර්ති ප්‍රදර්ශනයක් විවෘත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>தேசிய கலைக்கூடத்தில் வரலாற்று சிறப்புமிக்க ஓவிய மற்றும் சிற்ப கண்காட்சி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8683, '2026-09-29 15:50:34', '2026-09-29 15:50:34', '2026-09-29 15:50:34', '[79,80,81,82]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 79, 'sri-lankan-traditional-drumming-and-kandyan-dance-ensemble-tours-europe', 'Sri Lankan Traditional Drumming and Kandyan Dance Ensemble Tours Europe', 'දේශීය බෙර වාදන සහ උඩරට නැටුම් ශිල්පීන් යුරෝපීය සංචාරයක් අරඹයි', 'இலங்கையின் பாரம்பரிய நடனம் மற்றும் மேள வாத்திய கலைஞர்கள் ஐரோப்பிய பயணம்', 'Sri Lankan Traditional Drumming and Kandyan Dance Ensemble Tours Europe. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'දේශීය බෙර වාදන සහ උඩරට නැටුම් ශිල්පීන් යුරෝපීය සංචාරයක් අරඹයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கையின் பாரம்பரிய நடனம் மற்றும் மேள வாத்திய கலைஞர்கள் ஐரோப்பிய பயணம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lankan Traditional Drumming and Kandyan Dance Ensemble Tours Europe. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>දේශීය බෙර වාදන සහ උඩරට නැටුම් ශිල්පීන් යුරෝපීය සංචාරයක් අරඹයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கையின் பாரம்பரிய நடனம் மற்றும் மேள வாத்திய கலைஞர்கள் ஐரோப்பிய பயணம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 5779, '2026-09-29 12:09:47', '2026-09-29 12:09:47', '2026-09-29 12:09:47', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 80, 'global-streaming-giant-greenlights-first-original-drama-series-produced-in-colombo', 'Global Streaming Giant Greenlights First Original Drama Series Produced in Colombo', 'ජාත්‍යන්තර ප්‍රවාහ සේවාවක් මගින් මෙරටදී නිර්මාණය වන නව ටෙලි නාට්‍ය මාලාවක්', 'சர்வதேச இணையத்தள சேவை இலங்கையில் புதிய தொலைக்காட்சி தொடரை தயாரிக்கிறது', 'Global Streaming Giant Greenlights First Original Drama Series Produced in Colombo. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ජාත්‍යන්තර ප්‍රවාහ සේවාවක් මගින් මෙරටදී නිර්මාණය වන නව ටෙලි නාට්‍ය මාලාවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சர்வதேச இணையத்தள சேவை இலங்கையில் புதிய தொலைக்காட்சி தொடரை தயாரிக்கிறது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Global Streaming Giant Greenlights First Original Drama Series Produced in Colombo. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ජාත්‍යන්තර ප්‍රවාහ සේවාවක් මගින් මෙරටදී නිර්මාණය වන නව ටෙලි නාට්‍ය මාලාවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சர்வதேச இணையத்தள சேவை இலங்கையில் புதிய தொலைக்காட்சி தொடரை தயாரிக்கிறது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 9443, '2026-09-29 09:35:15', '2026-09-29 09:35:15', '2026-09-29 09:35:15', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 81, 'annual-colombo-fashion-week-celebrates-sustainable-high-fashion-innovation', 'Annual Colombo Fashion Week Celebrates Sustainable High-Fashion Innovation', 'කොළඹ විලාසිතා සතියේදී දේශීය මෝස්තර නිර්මාණ ශිල්පීන්ගේ දස්කම්', 'கொழும்பு ஆடை அலங்கார வாரத்தில் உள்ளூர் வடிவமைப்பாளர்களின் புதிய படைப்புகள்', 'Annual Colombo Fashion Week Celebrates Sustainable High-Fashion Innovation. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ විලාසිතා සතියේදී දේශීය මෝස්තර නිර්මාණ ශිල්පීන්ගේ දස්කම්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு ஆடை அலங்கார வாரத்தில் உள்ளூர் வடிவமைப்பாளர்களின் புதிய படைப்புகள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Annual Colombo Fashion Week Celebrates Sustainable High-Fashion Innovation. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ විලාසිතා සතියේදී දේශීය මෝස්තර නිර්මාණ ශිල්පීන්ගේ දස්කම්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு ஆடை அலங்கார வாரத்தில் உள்ளூர் வடிவமைப்பாளர்களின் புதிய படைப்புகள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 3077, '2026-09-29 06:43:11', '2026-09-29 06:43:11', '2026-09-29 06:43:11', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 82, 'chitrasena-dance-academy-commemorates-centenary-with-landmark-ballet-premiere', 'Chitrasena Dance Academy Commemorates Centenary with Landmark Ballet Premiere', 'චිත්‍රසේන නාට්‍ය කලාවේ ශත සංවත්සරය සමරමින් නව මුද්‍රා නාට්‍යයක්', 'சித்ரசேன நடனப் பள்ளியின் நூற்றாண்டு விழாவை முன்னிட்டு புதிய பாலே நடனம்', 'Chitrasena Dance Academy Commemorates Centenary with Landmark Ballet Premiere. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'චිත්‍රසේන නාට්‍ය කලාවේ ශත සංවත්සරය සමරමින් නව මුද්‍රා නාට්‍යයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சித்ரசேன நடனப் பள்ளியின் நூற்றாண்டு விழாவை முன்னிட்டு புதிய பாலே நடனம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Chitrasena Dance Academy Commemorates Centenary with Landmark Ballet Premiere. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>චිත්‍රසේන නාට්‍ය කලාවේ ශත සංවත්සරය සමරමින් නව මුද්‍රා නාට්‍යයක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சித்ரசேன நடனப் பள்ளியின் நூற்றாண்டு விழாவை முன்னிட்டு புதிய பாலே நடனம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 4350, '2026-09-29 04:12:14', '2026-09-29 04:12:14', '2026-09-29 04:12:14', '[83,84,85,86]', 'https://www.youtube.com/watch?v=kJQP7kiw5Fk', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 5, 83, 'boutique-short-film-festival-at-regal-cinema-spotlights-next-gen-directors', 'Boutique Short Film Festival at Regal Cinema Spotlights Next-Gen Directors', 'රීගල් සිනමාහලේදී පැවති කෙටි චිත්‍රපට උළෙලේදී නවක අධ්‍යක්ෂවරුන්ට ඇගයීම්', 'ரீகல் திரையரங்கில் நடைபெற்ற குறும்பட விழாவில் இளம் இயக்குனர்கள் கௌரவிப்பு', 'Boutique Short Film Festival at Regal Cinema Spotlights Next-Gen Directors. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'රීගල් සිනමාහලේදී පැවති කෙටි චිත්‍රපට උළෙලේදී නවක අධ්‍යක්ෂවරුන්ට ඇගයීම්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ரீகல் திரையரங்கில் நடைபெற்ற குறும்பட விழாவில் இளம் இயக்குனர்கள் கௌரவிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Boutique Short Film Festival at Regal Cinema Spotlights Next-Gen Directors. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>රීගල් සිනමාහලේදී පැවති කෙටි චිත්‍රපට උළෙලේදී නවක අධ්‍යක්ෂවරුන්ට ඇගයීම්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ரீகல் திரையரங்கில் நடைபெற்ற குறும்பட விழாவில் இளம் இயக்குனர்கள் கௌரவிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2169, '2026-09-29 00:55:37', '2026-09-29 00:55:37', '2026-09-29 00:55:37', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 84, 'sri-lanka-telecom-regulatory-commission-clears-nationwide-commercial-5g-launch', 'Sri Lanka Telecom Regulatory Commission Clears Nationwide Commercial 5G Launch', 'ශ්‍රී ලංකාව පුරා 5G ජංගම දුරකථන සබඳතා ව්‍යාප්ත කිරීමට නියාමන කොමිසමේ අනුමැතිය', 'இலங்கை முழுவதும் 5G தொலைத்தொடர்பு சேவைகளை விரிவுபடுத்த அனுமதி', 'Sri Lanka Telecom Regulatory Commission Clears Nationwide Commercial 5G Launch. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ශ්‍රී ලංකාව පුරා 5G ජංගම දුරකථන සබඳතා ව්‍යාප්ත කිරීමට නියාමන කොමිසමේ අනුමැතිය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'இலங்கை முழுவதும் 5G தொலைத்தொடர்பு சேவைகளை விரிவுபடுத்த அனுமதி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lanka Telecom Regulatory Commission Clears Nationwide Commercial 5G Launch. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ශ්‍රී ලංකාව පුරා 5G ජංගම දුරකථන සබඳතා ව්‍යාප්ත කිරීමට නියාමන කොමිසමේ අනුමැතිය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>இலங்கை முழுவதும் 5G தொலைத்தொடர்பு சேவைகளை விரிவுபடுத்த அனுமதி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2430, '2026-09-28 22:39:20', '2026-09-28 22:39:20', '2026-09-28 22:39:20', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 85, 'local-ai-startup-pioneers-multilingual-sinhala-and-tamil-large-language-model', 'Local AI Startup Pioneers Multilingual Sinhala and Tamil Large Language Model', 'සිංහල සහ දෙමළ භාෂා සඳහා වන නවතම කෘත්‍රිම බුද්ධි ආකෘතියක් එළිදක්වයි', 'சிங்களம் மற்றும் தமிழ் மொழிகளுக்கான பிரத்தியேக செயற்கை நுண்ணறிவு மாதிரி அறிமுகம்', 'Local AI Startup Pioneers Multilingual Sinhala and Tamil Large Language Model. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'සිංහල සහ දෙමළ භාෂා සඳහා වන නවතම කෘත්‍රිම බුද්ධි ආකෘතියක් එළිදක්වයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சிங்களம் மற்றும் தமிழ் மொழிகளுக்கான பிரத்தியேக செயற்கை நுண்ணறிவு மாதிரி அறிமுகம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Local AI Startup Pioneers Multilingual Sinhala and Tamil Large Language Model. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සිංහල සහ දෙමළ භාෂා සඳහා වන නවතම කෘත්‍රිම බුද්ධි ආකෘතියක් එළිදක්වයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சிங்களம் மற்றும் தமிழ் மொழிகளுக்கான பிரத்தியேக செயற்கை நுண்ணறிவு மாதிரி அறிமுகம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6924, '2026-09-28 19:26:58', '2026-09-28 19:26:58', '2026-09-28 19:26:58', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 86, 'national-science-foundation-funds-breakthrough-marine-microplastics-research', 'National Science Foundation Funds Breakthrough Marine Microplastics Research', 'සාගර ක්ෂුද්‍ර ප්ලාස්ටික් අවම කිරීමේ පර්යේෂණයක් වෙනුවෙන් ජාතික විද්‍යා පදනමේ අනුග්‍රහය', 'கடல்சார் பிளாஸ்டிக் மாசுபாட்டை கட்டுப்படுத்தும் புதிய ஆய்வுக்கு நிதி உதவி', 'National Science Foundation Funds Breakthrough Marine Microplastics Research. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'සාගර ක්ෂුද්‍ර ප්ලාස්ටික් අවම කිරීමේ පර්යේෂණයක් වෙනුවෙන් ජාතික විද්‍යා පදනමේ අනුග්‍රහය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கடல்சார் பிளாஸ்டிக் மாசுபாட்டை கட்டுப்படுத்தும் புதிய ஆய்வுக்கு நிதி உதவி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>National Science Foundation Funds Breakthrough Marine Microplastics Research. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සාගර ක්ෂුද්‍ර ප්ලාස්ටික් අවම කිරීමේ පර්යේෂණයක් වෙනුවෙන් ජාතික විද්‍යා පදනමේ අනුග්‍රහය. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கடல்சார் பிளாஸ்டிக் மாசுபாட்டை கட்டுப்படுத்தும் புதிய ஆய்வுக்கு நிதி உதவி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2813, '2026-09-28 17:06:51', '2026-09-28 17:06:51', '2026-09-28 17:06:51', '[1,2,3,4]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 1, 'arthur-c-clarke-institute-tracks-historic-asteroid-flyby-with-astronomical-radar', 'Arthur C. Clarke Institute Tracks Historic Asteroid Flyby with Astronomical Radar', 'ආතර් සී ක්ලාක් ආයතනය පෘථිවිය අසලින් ගිය උල්කාශ්මයක් සාර්ථකව නිරීක්ෂණය කරයි', 'ஆர்தர் சி கிளார்க் நிறுவனம் விண்வெளி சிறுகோள் ஒன்றை வெற்றிகரமாக அவதானித்தது', 'Arthur C. Clarke Institute Tracks Historic Asteroid Flyby with Astronomical Radar. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ආතර් සී ක්ලාක් ආයතනය පෘථිවිය අසලින් ගිය උල්කාශ්මයක් සාර්ථකව නිරීක්ෂණය කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஆர்தர் சி கிளார்க் நிறுவனம் விண்வெளி சிறுகோள் ஒன்றை வெற்றிகரமாக அவதானித்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Arthur C. Clarke Institute Tracks Historic Asteroid Flyby with Astronomical Radar. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ආතර් සී ක්ලාක් ආයතනය පෘථිවිය අසලින් ගිය උල්කාශ්මයක් සාර්ථකව නිරීක්ෂණය කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஆர்தர் சி கிளார்க் நிறுவனம் விண்வெளி சிறுகோள் ஒன்றை வெற்றிகரமாக அவதானித்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 5277, '2026-09-28 13:51:49', '2026-09-28 13:51:49', '2026-09-28 13:51:49', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 2, 'colombo-port-deploys-ai-driven-autonomous-electric-container-transport-fleet', 'Colombo Port Deploys AI-Driven Autonomous Electric Container Transport Fleet', 'කොළඹ වරාය තුළ බහාලුම් ප්‍රවාහනයට ස්වයංක්‍රීය විද්‍යුත් රථ පෙළක් හඳුන්වා දෙයි', 'கொழும்பு துறைமுகத்தில் கொள்கலன் கொண்டுசெல்ல தானியங்கி மின்சார வாகனங்கள்', 'Colombo Port Deploys AI-Driven Autonomous Electric Container Transport Fleet. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කොළඹ වරාය තුළ බහාලුම් ප්‍රවාහනයට ස්වයංක්‍රීය විද්‍යුත් රථ පෙළක් හඳුන්වා දෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கொழும்பு துறைமுகத்தில் கொள்கலன் கொண்டுசெல்ல தானியங்கி மின்சார வாகனங்கள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Colombo Port Deploys AI-Driven Autonomous Electric Container Transport Fleet. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කොළඹ වරාය තුළ බහාලුම් ප්‍රවාහනයට ස්වයංක්‍රීය විද්‍යුත් රථ පෙළක් හඳුන්වා දෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கொழும்பு துறைமுகத்தில் கொள்கலன் கொண்டுசெல்ல தானியங்கி மின்சார வாகனங்கள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 899, '2026-09-28 10:54:45', '2026-09-28 10:54:45', '2026-09-28 10:54:45', '[]', 'https://www.youtube.com/watch?v=fJ9rUzIMcZQ', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 3, 'ministry-of-technology-launches-national-cyber-security-command-center', 'Ministry of Technology Launches National Cyber Security Command Center', 'සයිබර් ආරක්ෂාව සහ ඩිජිටල් දත්ත සුරැකීම සඳහා ජාතික මෙහෙයුම් මැදිරියක්', 'சைபர் பாதுகாப்பு மற்றும் டிஜிட்டல் தரவு பாதுகாப்பிற்கான தேசிய கட்டுப்பாட்டு மையம் திறப்பு', 'Ministry of Technology Launches National Cyber Security Command Center. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'සයිබර් ආරක්ෂාව සහ ඩිජිටල් දත්ත සුරැකීම සඳහා ජාතික මෙහෙයුම් මැදිරියක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சைபர் பாதுகாப்பு மற்றும் டிஜிட்டல் தரவு பாதுகாப்பிற்கான தேசிய கட்டுப்பாட்டு மையம் திறப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Ministry of Technology Launches National Cyber Security Command Center. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සයිබර් ආරක්ෂාව සහ ඩිජිටල් දත්ත සුරැකීම සඳහා ජාතික මෙහෙයුම් මැදිරියක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சைபர் பாதுகாப்பு மற்றும் டிஜிட்டல் தரவு பாதுகாப்பிற்கான தேசிய கட்டுப்பாட்டு மையம் திறப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 1158, '2026-09-28 08:08:57', '2026-09-28 08:08:57', '2026-09-28 08:08:57', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 4, 'sri-lankan-university-team-wins-global-nasa-space-apps-challenge-finals', 'Sri Lankan University Team Wins Global NASA Space Apps Challenge Finals', 'නාසා අභ්‍යවකාශ ඇප්ස් තරගාවලියේ ලෝක ශූරතාව ශ්‍රී ලාංකික සරසවි සිසුන්ට', 'நாசா சர்வதேச விண்வெளி மென்பொருள் போட்டியில் இலங்கை பல்கலைக்கழக மாணவர்கள் சாம்பியன்', 'Sri Lankan University Team Wins Global NASA Space Apps Challenge Finals. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'නාසා අභ්‍යවකාශ ඇප්ස් තරගාවලියේ ලෝක ශූරතාව ශ්‍රී ලාංකික සරසවි සිසුන්ට. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'நாசா சர்வதேச விண்வெளி மென்பொருள் போட்டியில் இலங்கை பல்கலைக்கழக மாணவர்கள் சாம்பியன். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Sri Lankan University Team Wins Global NASA Space Apps Challenge Finals. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නාසා අභ්‍යවකාශ ඇප්ස් තරගාවලියේ ලෝක ශූරතාව ශ්‍රී ලාංකික සරසවි සිසුන්ට. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>நாசா சர்வதேச விண்வெளி மென்பொருள் போட்டியில் இலங்கை பல்கலைக்கழக மாணவர்கள் சாம்பியன். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8207, '2026-09-28 05:19:05', '2026-09-28 05:19:05', '2026-09-28 05:19:05', '[13,14,15,16]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 13, 'fintech-revolution-over-80-of-government-utility-bills-now-settled-digitally', 'Fintech Revolution: Over 80% of Government Utility Bills Now Settled Digitally', 'රාජ්‍ය බිල්පත් ගෙවීම්වලින් සියයට 80 කට වඩා ඩිජිටල් ක්‍රමයට සිදුකෙරේ', 'அரச கட்டண செலுத்தல்களில் 80% இற்கும் அதிகமானவை டிஜிட்டல் முறைக்கு மாற்றம்', 'Fintech Revolution: Over 80% of Government Utility Bills Now Settled Digitally. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'රාජ්‍ය බිල්පත් ගෙවීම්වලින් සියයට 80 කට වඩා ඩිජිටල් ක්‍රමයට සිදුකෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'அரச கட்டண செலுத்தல்களில் 80% இற்கும் அதிகமானவை டிஜிட்டல் முறைக்கு மாற்றம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Fintech Revolution: Over 80% of Government Utility Bills Now Settled Digitally. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>රාජ්‍ය බිල්පත් ගෙවීම්වලින් සියයට 80 කට වඩා ඩිජිටල් ක්‍රමයට සිදුකෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>அரச கட்டண செலுத்தல்களில் 80% இற்கும் அதிகமானவை டிஜிட்டல் முறைக்கு மாற்றம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8544, '2026-09-28 02:43:31', '2026-09-28 02:43:31', '2026-09-28 02:43:31', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 14, 'quantum-computing-research-hub-established-at-university-of-moratuwa', 'Quantum Computing Research Hub Established at University of Moratuwa', 'මොරටුව විශ්වවිද්‍යාලයේ ක්වොන්ටම් පරිගණක තාක්ෂණ පර්යේෂණාගාරයක් ස්ථාපිත කෙරේ', 'மொறட்டுவ பல்கலைக்கழகத்தில் குவாண்டம் கணினி தொழில்நுட்ப ஆய்வு கூடம் உருவாக்கம்', 'Quantum Computing Research Hub Established at University of Moratuwa. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මොරටුව විශ්වවිද්‍යාලයේ ක්වොන්ටම් පරිගණක තාක්ෂණ පර්යේෂණාගාරයක් ස්ථාපිත කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'மொறட்டுவ பல்கலைக்கழகத்தில் குவாண்டம் கணினி தொழில்நுட்ப ஆய்வு கூடம் உருவாக்கம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Quantum Computing Research Hub Established at University of Moratuwa. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මොරටුව විශ්වවිද්‍යාලයේ ක්වොන්ටම් පරිගණක තාක්ෂණ පර්යේෂණාගාරයක් ස්ථාපිත කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>மொறட்டுவ பல்கலைக்கழகத்தில் குவாண்டம் கணினி தொழில்நுட்ப ஆய்வு கூடம் உருவாக்கம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2201, '2026-09-27 23:40:54', '2026-09-27 23:40:54', '2026-09-27 23:40:54', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 15, 'farmers-embrace-drone-remote-sensing-for-precision-fertilizer-and-crop-management', 'Farmers Embrace Drone Remote Sensing for Precision Fertilizer and Crop Management', 'කෘෂිකර්මාන්තය සඳහා ඩ්‍රෝන තාක්ෂණය යොදාගැනීමෙන් පොහොර නාස්තිය අවම වෙයි', 'விவசாயத்தில் ட்ரோன் தொழில்நுட்பத்தை பயன்படுத்தி உர விரயத்தை கட்டுப்படுத்திய விவசாயிகள்', 'Farmers Embrace Drone Remote Sensing for Precision Fertilizer and Crop Management. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කෘෂිකර්මාන්තය සඳහා ඩ්‍රෝන තාක්ෂණය යොදාගැනීමෙන් පොහොර නාස්තිය අවම වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'விவசாயத்தில் ட்ரோன் தொழில்நுட்பத்தை பயன்படுத்தி உர விரயத்தை கட்டுப்படுத்திய விவசாயிகள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Farmers Embrace Drone Remote Sensing for Precision Fertilizer and Crop Management. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කෘෂිකර්මාන්තය සඳහා ඩ්‍රෝන තාක්ෂණය යොදාගැනීමෙන් පොහොර නාස්තිය අවම වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>விவசாயத்தில் ட்ரோன் தொழில்நுட்பத்தை பயன்படுத்தி உர விரயத்தை கட்டுப்படுத்திய விவசாயிகள். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2044, '2026-09-27 20:33:15', '2026-09-27 20:33:15', '2026-09-27 20:33:15', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 16, 'breakthrough-indigenous-water-filtration-unit-removes-heavy-metals-in-dry-zone', 'Breakthrough Indigenous Water Filtration Unit Removes Heavy Metals in Dry Zone', 'වියළි කලාපයේ ජලයේ ඇති බැර ලෝහ ඉවත් කිරීමට දේශීය නව නිපැයුමක්', 'உலர் வலய குடிநீரில் உள்ள நச்சுக்களை நீக்கும் புதிய உள்நாட்டு நீர் சுத்திகரிப்பு இயந்திரம்', 'Breakthrough Indigenous Water Filtration Unit Removes Heavy Metals in Dry Zone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'වියළි කලාපයේ ජලයේ ඇති බැර ලෝහ ඉවත් කිරීමට දේශීය නව නිපැයුමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'உலர் வலய குடிநீரில் உள்ள நச்சுக்களை நீக்கும் புதிய உள்நாட்டு நீர் சுத்திகரிப்பு இயந்திரம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Breakthrough Indigenous Water Filtration Unit Removes Heavy Metals in Dry Zone. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>වියළි කලාපයේ ජලයේ ඇති බැර ලෝහ ඉවත් කිරීමට දේශීය නව නිපැයුමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>உலர் வலய குடிநீரில் உள்ள நச்சுக்களை நீக்கும் புதிய உள்நாட்டு நீர் சுத்திகரிப்பு இயந்திரம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 1, 10, 4719, '2026-09-27 18:26:34', '2026-09-27 18:26:34', '2026-09-27 18:26:34', '[17,18,19,20]', 'https://www.youtube.com/watch?v=kXYiU_JCYtU', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 17, 'global-cloud-providers-establish-low-latency-edge-data-centers-in-colombo', 'Global Cloud Providers Establish Low-Latency Edge Data Centers in Colombo', 'ලොව ප්‍රමුඛ ක්ලවුඩ් සේවා සපයන්නන් කොළඹදී නව දත්ත මධ්‍යස්ථාන ආරම්භ කරයි', 'பிரபல கிளவுட் நிறுவனங்கள் கொழும்பில் புதிய தரவு மையங்களை நிறுவியுள்ளன', 'Global Cloud Providers Establish Low-Latency Edge Data Centers in Colombo. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ලොව ප්‍රමුඛ ක්ලවුඩ් සේවා සපයන්නන් කොළඹදී නව දත්ත මධ්‍යස්ථාන ආරම්භ කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'பிரபல கிளவுட் நிறுவனங்கள் கொழும்பில் புதிய தரவு மையங்களை நிறுவியுள்ளன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Global Cloud Providers Establish Low-Latency Edge Data Centers in Colombo. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ලොව ප්‍රමුඛ ක්ලවුඩ් සේවා සපයන්නන් කොළඹදී නව දත්ත මධ්‍යස්ථාන ආරම්භ කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பிரபல கிளவுட் நிறுவனங்கள் கொழும்பில் புதிய தரவு மையங்களை நிறுவியுள்ளன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 4132, '2026-09-27 15:38:19', '2026-09-27 15:38:19', '2026-09-27 15:38:19', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 6, 18, 'biomedical-engineers-develop-low-cost-3d-printed-prosthetic-limbs-in-kandy', 'Biomedical Engineers Develop Low-Cost 3D-Printed Prosthetic Limbs in Kandy', 'මහනුවරදී ත්‍රිමාණ මුද්‍රණ තාක්ෂණයෙන් අඩු වියදම් කෘත්‍රිම අත්පා නිපදවයි', 'கண்டியில் 3D அச்சு தொழில்நுட்பத்தின் மூலம் குறைந்த செலவிலான செயற்கை அவயவங்கள் உற்பத்தி', 'Biomedical Engineers Develop Low-Cost 3D-Printed Prosthetic Limbs in Kandy. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මහනුවරදී ත්‍රිමාණ මුද්‍රණ තාක්ෂණයෙන් අඩු වියදම් කෘත්‍රිම අත්පා නිපදවයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கண்டியில் 3D அச்சு தொழில்நுட்பத்தின் மூலம் குறைந்த செலவிலான செயற்கை அவயவங்கள் உற்பத்தி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Biomedical Engineers Develop Low-Cost 3D-Printed Prosthetic Limbs in Kandy. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මහනුවරදී ත්‍රිමාණ මුද්‍රණ තාක්ෂණයෙන් අඩු වියදම් කෘත්‍රිම අත්පා නිපදවයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கண்டியில் 3D அச்சு தொழில்நுட்பத்தின் மூலம் குறைந்த செலவிலான செயற்கை அவயவங்கள் உற்பத்தி. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 3409, '2026-09-27 12:02:07', '2026-09-27 12:02:07', '2026-09-27 12:02:07', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 19, 'united-nations-general-assembly-adopts-comprehensive-global-peace-resolution', 'United Nations General Assembly Adopts Comprehensive Global Peace Resolution', 'ගෝලීය සාමය සහ තිරසාර සංවර්ධනය පිළිබඳ නව යෝජනාවක් එක්සත් ජාතීන්ගේ මහා මණ්ඩලයේදී සම්මත වෙයි', 'ஐக்கிய நாடுகள் பொதுச் சபையில் உலகளாவிய அமைதிக்கான புதிய தீர்மானம் நிறைவேற்றம்', 'United Nations General Assembly Adopts Comprehensive Global Peace Resolution. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ගෝලීය සාමය සහ තිරසාර සංවර්ධනය පිළිබඳ නව යෝජනාවක් එක්සත් ජාතීන්ගේ මහා මණ්ඩලයේදී සම්මත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஐக்கிய நாடுகள் பொதுச் சபையில் உலகளாவிய அமைதிக்கான புதிய தீர்மானம் நிறைவேற்றம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>United Nations General Assembly Adopts Comprehensive Global Peace Resolution. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ගෝලීය සාමය සහ තිරසාර සංවර්ධනය පිළිබඳ නව යෝජනාවක් එක්සත් ජාතීන්ගේ මහා මණ්ඩලයේදී සම්මත වෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஐக்கிய நாடுகள் பொதுச் சபையில் உலகளாவிய அமைதிக்கான புதிய தீர்மானம் நிறைவேற்றம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 1116, '2026-09-27 09:42:14', '2026-09-27 09:42:14', '2026-09-27 09:42:14', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 20, 'global-climate-summit-in-geneva-reaches-consensus-on-green-transition-funds', 'Global Climate Summit in Geneva Reaches Consensus on Green Transition Funds', 'ජිනීවා නුවර පැවති දේශගුණික සමුළුවේදී සංවර්ධනය වෙමින් පවතින රටවලට අරමුදල් සම්පාදනයට එකඟතාව', 'ஜெனீவா காலநிலை மாநாட்டில் அபிவிருத்தியடைந்து வரும் நாடுகளுக்கான நிதி உதவிக்கு உடன்பாடு', 'Global Climate Summit in Geneva Reaches Consensus on Green Transition Funds. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ජිනීවා නුවර පැවති දේශගුණික සමුළුවේදී සංවර්ධනය වෙමින් පවතින රටවලට අරමුදල් සම්පාදනයට එකඟතාව. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஜெனீவா காலநிலை மாநாட்டில் அபிவிருத்தியடைந்து வரும் நாடுகளுக்கான நிதி உதவிக்கு உடன்பாடு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Global Climate Summit in Geneva Reaches Consensus on Green Transition Funds. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ජිනීවා නුවර පැවති දේශගුණික සමුළුවේදී සංවර්ධනය වෙමින් පවතින රටවලට අරමුදල් සම්පාදනයට එකඟතාව. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஜெனீவா காலநிலை மாநாட்டில் அபிவிருத்தியடைந்து வரும் நாடுகளுக்கான நிதி உதவிக்கு உடன்பாடு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 959, '2026-09-27 06:42:46', '2026-09-27 06:42:46', '2026-09-27 06:42:46', '[22,23,24,25]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 22, 'international-monetary-fund-forecasts-resilient-growth-for-developing-asian-economies', 'International Monetary Fund Forecasts Resilient Growth for Developing Asian Economies', 'ආසියානු කලාපයේ ආර්ථික වර්ධනය ස්ථාවරව පවතින බව ජාත්‍යන්තර මූල්‍ය අරමුදල පවසයි', 'ஆசிய பிராந்தியத்தின் பொருளாதார வளர்ச்சி நிலையாக இருக்கும் என சர்வதேச நாணய நிதியம் கணிப்பு', 'International Monetary Fund Forecasts Resilient Growth for Developing Asian Economies. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ආසියානු කලාපයේ ආර්ථික වර්ධනය ස්ථාවරව පවතින බව ජාත්‍යන්තර මූල්‍ය අරමුදල පවසයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஆசிய பிராந்தியத்தின் பொருளாதார வளர்ச்சி நிலையாக இருக்கும் என சர்வதேச நாணய நிதியம் கணிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>International Monetary Fund Forecasts Resilient Growth for Developing Asian Economies. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ආසියානු කලාපයේ ආර්ථික වර්ධනය ස්ථාවරව පවතින බව ජාත්‍යන්තර මූල්‍ය අරමුදල පවසයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஆசிய பிராந்தியத்தின் பொருளாதார வளர்ச்சி நிலையாக இருக்கும் என சர்வதேச நாணய நிதியம் கணிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 713, '2026-09-27 03:33:35', '2026-09-27 03:33:35', '2026-09-27 03:33:35', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 23, 'spacex-starship-completes-orbital-re-entry-test-in-milestone-for-deep-space-flight', 'SpaceX Starship Completes Orbital Re-entry Test in Milestone for Deep-Space Flight', 'අඟහරු ගවේෂණය වෙනුවෙන් ස්පේස් එක්ස් ස්ටාර්ෂිප් යානය සාර්ථක කක්ෂීය පරීක්ෂණයක් නිම කරයි', 'விண்வெளி ஆய்விற்கான ஸ்பேஸ் எக்ஸ் ஸ்டார்ஷிப் விண்கலம் வெற்றிகரமான சுற்றுப்பாதை சோதனையை நிறைவு செய்தது', 'SpaceX Starship Completes Orbital Re-entry Test in Milestone for Deep-Space Flight. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'අඟහරු ගවේෂණය වෙනුවෙන් ස්පේස් එක්ස් ස්ටාර්ෂිප් යානය සාර්ථක කක්ෂීය පරීක්ෂණයක් නිම කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'விண்வெளி ஆய்விற்கான ஸ்பேஸ் எக்ஸ் ஸ்டார்ஷிப் விண்கலம் வெற்றிகரமான சுற்றுப்பாதை சோதனையை நிறைவு செய்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>SpaceX Starship Completes Orbital Re-entry Test in Milestone for Deep-Space Flight. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>අඟහරු ගවේෂණය වෙනුවෙන් ස්පේස් එක්ස් ස්ටාර්ෂිප් යානය සාර්ථක කක්ෂීය පරීක්ෂණයක් නිම කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>விண்வெளி ஆய்விற்கான ஸ்பேஸ் எக்ஸ் ஸ்டார்ஷிப் விண்கலம் வெற்றிகரமான சுற்றுப்பாதை சோதனையை நிறைவு செய்தது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8697, '2026-09-27 00:51:51', '2026-09-27 00:51:51', '2026-09-27 00:51:51', '[]', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 24, 'european-union-signs-broad-strategic-green-energy-and-trade-partnership', 'European Union Signs Broad Strategic Green Energy and Trade Partnership', 'යුරෝපා සංගමය නව හරිත බලශක්ති සහ වෙළෙඳ ගිවිසුමකට අත්සන් තබයි', 'ஐரோப்பிய ஒன்றியம் புதிய பசுமை சக்தி மற்றும் வர்த்தக ஒப்பந்தத்தில் கைச்சாத்திட்டது', 'European Union Signs Broad Strategic Green Energy and Trade Partnership. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'යුරෝපා සංගමය නව හරිත බලශක්ති සහ වෙළෙඳ ගිවිසුමකට අත්සන් තබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஐரோப்பிய ஒன்றியம் புதிய பசுமை சக்தி மற்றும் வர்த்தக ஒப்பந்தத்தில் கைச்சாத்திட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>European Union Signs Broad Strategic Green Energy and Trade Partnership. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>යුරෝපා සංගමය නව හරිත බලශක්ති සහ වෙළෙඳ ගිවිසුමකට අත්සන් තබයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஐரோப்பிய ஒன்றியம் புதிய பசுமை சக்தி மற்றும் வர்த்தக ஒப்பந்தத்தில் கைச்சாத்திட்டது. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 1794, '2026-09-26 21:51:12', '2026-09-26 21:51:12', '2026-09-26 21:51:12', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 25, 'g20-finance-ministers-agree-on-coordinated-global-digital-taxation-guidelines', 'G20 Finance Ministers Agree on Coordinated Global Digital Taxation Guidelines', 'ජී20 මුදල් ඇමැතිවරුන් ඩිජිටල් බහුජාතික සමාගම් සඳහා පොදු බදු ප්‍රතිපත්තියක් සම්මත කරයි', 'ஜி20 நிதி அமைச்சர்கள் பன்னாட்டு டிஜிட்டல் நிறுவனங்களுக்கான பொதுவான வரி விதிப்புக்கு ஒப்புதல்', 'G20 Finance Ministers Agree on Coordinated Global Digital Taxation Guidelines. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ජී20 මුදල් ඇමැතිවරුන් ඩිජිටල් බහුජාතික සමාගම් සඳහා පොදු බදු ප්‍රතිපත්තියක් සම්මත කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஜி20 நிதி அமைச்சர்கள் பன்னாட்டு டிஜிட்டல் நிறுவனங்களுக்கான பொதுவான வரி விதிப்புக்கு ஒப்புதல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>G20 Finance Ministers Agree on Coordinated Global Digital Taxation Guidelines. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ජී20 මුදල් ඇමැතිවරුන් ඩිජිටල් බහුජාතික සමාගම් සඳහා පොදු බදු ප්‍රතිපත්තියක් සම්මත කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஜி20 நிதி அமைச்சர்கள் பன்னாட்டு டிஜிட்டல் நிறுவனங்களுக்கான பொதுவான வரி விதிப்புக்கு ஒப்புதல். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 2454, '2026-09-26 19:30:11', '2026-09-26 19:30:11', '2026-09-26 19:30:11', '[26,27,28,29]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 26, 'world-health-organization-declares-elimination-of-multiple-tropical-diseases', 'World Health Organization Declares Elimination of Multiple Tropical Diseases', 'නිවර්තන කලාපීය බෝවන රෝග කිහිපයක් සාර්ථකව තුරන් කළ බව ලෝක සෞඛ්‍ය සංවිධානය නිවේදනය කරයි', 'பல வெப்பமண்டல தொற்றுநோய்கள் கட்டுப்படுத்தப்பட்டதாக உலக சுகாதார ஸ்தாபனம் அறிவிப்பு', 'World Health Organization Declares Elimination of Multiple Tropical Diseases. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'නිවර්තන කලාපීය බෝවන රෝග කිහිපයක් සාර්ථකව තුරන් කළ බව ලෝක සෞඛ්‍ය සංවිධානය නිවේදනය කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'பல வெப்பமண்டல தொற்றுநோய்கள் கட்டுப்படுத்தப்பட்டதாக உலக சுகாதார ஸ்தாபனம் அறிவிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>World Health Organization Declares Elimination of Multiple Tropical Diseases. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නිවර්තන කලාපීය බෝවන රෝග කිහිපයක් සාර්ථකව තුරන් කළ බව ලෝක සෞඛ්‍ය සංවිධානය නිවේදනය කරයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>பல வெப்பமண்டல தொற்றுநோய்கள் கட்டுப்படுத்தப்பட்டதாக உலக சுகாதார ஸ்தாபனம் அறிவிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 1675, '2026-09-26 17:00:22', '2026-09-26 17:00:22', '2026-09-26 17:00:22', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 27, 'asia-pacific-cooperation-forum-agrees-on-simplified-cross-border-e-commerce', 'Asia-Pacific Cooperation Forum Agrees on Simplified Cross-Border E-Commerce', 'ආසියා ශාන්තිකර කලාපය තුළ ඩිජිටල් වෙළෙඳාම පහසු කිරීමට නව ගිවිසුමක්', 'ஆசிய-பசிபிக் வலயத்தில் டிஜிட்டல் வர்த்தகத்தை எளிமைப்படுத்த புதிய ஒப்பந்தம்', 'Asia-Pacific Cooperation Forum Agrees on Simplified Cross-Border E-Commerce. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ආසියා ශාන්තිකර කලාපය තුළ ඩිජිටල් වෙළෙඳාම පහසු කිරීමට නව ගිවිසුමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'ஆசிய-பசிபிக் வலயத்தில் டிஜிட்டல் வர்த்தகத்தை எளிமைப்படுத்த புதிய ஒப்பந்தம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Asia-Pacific Cooperation Forum Agrees on Simplified Cross-Border E-Commerce. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ආසියා ශාන්තිකර කලාපය තුළ ඩිජිටල් වෙළෙඳාම පහසු කිරීමට නව ගිවිසුමක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>ஆசிய-பசிபிக் வலயத்தில் டிஜிட்டல் வர்த்தகத்தை எளிமைப்படுத்த புதிய ஒப்பந்தம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6257, '2026-09-26 13:58:39', '2026-09-26 13:58:39', '2026-09-26 13:58:39', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 28, 'historic-archaeological-discovery-unearthed-in-mediterranean-coastal-expedition', 'Historic Archaeological Discovery Unearthed in Mediterranean Coastal Expedition', 'මධ්‍යධරණී මුහුදු පත්ලෙන් වසර 2,500 කට පෙර ගිලී ගිය පැරණි නගරයක නටබුන් හමුවෙයි', 'மத்திய தரைக்கடல் பகுதியில் 2,500 ஆண்டுகள் பழமையான மூழ்கிய பண்டைய நகரத்தின் எச்சங்கள் கண்டுபிடிப்பு', 'Historic Archaeological Discovery Unearthed in Mediterranean Coastal Expedition. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'මධ්‍යධරණී මුහුදු පත්ලෙන් වසර 2,500 කට පෙර ගිලී ගිය පැරණි නගරයක නටබුන් හමුවෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'மத்திய தரைக்கடல் பகுதியில் 2,500 ஆண்டுகள் பழமையான மூழ்கிய பண்டைய நகரத்தின் எச்சங்கள் கண்டுபிடிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Historic Archaeological Discovery Unearthed in Mediterranean Coastal Expedition. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>මධ්‍යධරණී මුහුදු පත්ලෙන් වසර 2,500 කට පෙර ගිලී ගිය පැරණි නගරයක නටබුන් හමුවෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>மத்திய தரைக்கடல் பகுதியில் 2,500 ஆண்டுகள் பழமையான மூழ்கிய பண்டைய நகரத்தின் எச்சங்கள் கண்டுபிடிப்பு. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 6194, '2026-09-26 10:44:32', '2026-09-26 10:44:32', '2026-09-26 10:44:32', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 29, 'major-global-tech-giants-unveil-universal-interoperability-standard-for-quantum-devices', 'Major Global Tech Giants Unveil Universal Interoperability Standard for Quantum Devices', 'ක්වොන්ටම් තාක්ෂණික මෙවලම් සඳහා පොදු ජාත්‍යන්තර ප්‍රමිතියක් හඳුන්වා දෙයි', 'குவாண்டம் தொழில்நுட்ப சாதனங்களுக்கான பொதுவான சர்வதேச தர நிர்ணயம் அறிமுகம்', 'Major Global Tech Giants Unveil Universal Interoperability Standard for Quantum Devices. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'ක්වොන්ටම් තාක්ෂණික මෙවලම් සඳහා පොදු ජාත්‍යන්තර ප්‍රමිතියක් හඳුන්වා දෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'குவாண்டம் தொழில்நுட்ப சாதனங்களுக்கான பொதுவான சர்வதேச தர நிர்ணயம் அறிமுகம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Major Global Tech Giants Unveil Universal Interoperability Standard for Quantum Devices. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>ක්වොන්ටම් තාක්ෂණික මෙවලම් සඳහා පොදු ජාත්‍යන්තර ප්‍රමිතියක් හඳුන්වා දෙයි. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>குவாண்டம் தொழில்நுட்ப சாதனங்களுக்கான பொதுவான சர்வதேச தர நிர்ணயம் அறிமுகம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 1, 0, 0, 7943, '2026-09-26 08:27:38', '2026-09-26 08:27:38', '2026-09-26 08:27:38', '[30,31,32,33]', 'https://www.youtube.com/watch?v=9bZkp7q19f0', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 30, 'international-maritime-organization-mandates-lower-carbon-targets-for-cargo-fleets', 'International Maritime Organization Mandates Lower Carbon Targets for Cargo Fleets', 'සාගර නෞකා සඳහා පරිසර හිතකාමී නව කාබන් විමෝචන සීමා පනවා තිබේ', 'சரக்குக் கப்பல்களுக்கான புதிய சூழல் நட்பு குறைந்த கார்பன் உமிழ்வு இலக்குகள் நிர்ணயம்', 'International Maritime Organization Mandates Lower Carbon Targets for Cargo Fleets. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'සාගර නෞකා සඳහා පරිසර හිතකාමී නව කාබන් විමෝචන සීමා පනවා තිබේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'சரக்குக் கப்பல்களுக்கான புதிய சூழல் நட்பு குறைந்த கார்பன் உமிழ்வு இலக்குகள் நிர்ணயம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>International Maritime Organization Mandates Lower Carbon Targets for Cargo Fleets. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>සාගර නෞකා සඳහා පරිසර හිතකාමී නව කාබන් විමෝචන සීමා පනවා තිබේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>சரக்குக் கப்பல்களுக்கான புதிய சூழல் நட்பு குறைந்த கார்பன் உமிழ்வு இலக்குகள் நிர்ணயம். சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 4419, '2026-09-26 04:53:44', '2026-09-26 04:53:44', '2026-09-26 04:53:44', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 31, 'world-economic-forum-releases-global-human-capital-and-robotics-integration-study', 'World Economic Forum Releases Global Human Capital and Robotics Integration Study', 'කෘත්‍රිම බුද්ධිය සහ මිනිස් ශ්‍රමය ඒකාබද්ධ කිරීම පිළිබඳ නව ගෝලීය වාර්තාවක්', 'செயற்கை நுண்ணறிவு மற்றும் மனித உழைப்பு ஒருங்கிணைப்பு குறித்த புதிய உலகளாவிய அறிக்கை', 'World Economic Forum Releases Global Human Capital and Robotics Integration Study. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'කෘත්‍රිම බුද්ධිය සහ මිනිස් ශ්‍රමය ඒකාබද්ධ කිරීම පිළිබඳ නව ගෝලීය වාර්තාවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'செயற்கை நுண்ணறிவு மற்றும் மனித உழைப்பு ஒருங்கிணைப்பு குறித்த புதிய உலகளாவிய அறிக்கை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>World Economic Forum Releases Global Human Capital and Robotics Integration Study. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>කෘත්‍රිම බුද්ධිය සහ මිනිස් ශ්‍රමය ඒකාබද්ධ කිරීම පිළිබඳ නව ගෝලීය වාර්තාවක්. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>செயற்கை நுண்ணறிவு மற்றும் மனித உழைப்பு ஒருங்கிணைப்பு குறித்த புதிய உலகளாவிய அறிக்கை. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 1, 10, 6735, '2026-09-26 02:09:07', '2026-09-26 02:09:07', '2026-09-26 02:09:07', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
INSERT INTO `articles` (`author_id`, `category_id`, `featured_image_id`, `slug`, `title_en`, `title_si`, `title_ta`, `summary_en`, `summary_si`, `summary_ta`, `content_en`, `content_si`, `content_ta`, `status`, `is_breaking`, `is_featured`, `priority`, `views`, `published_at`, `created_at`, `updated_at`, `gallery_ids`, `video_url`, `tags`) VALUES (1, 7, 32, 'global-humanitarian-relief-operations-scale-up-emergency-food-aid-in-east-africa', 'Global Humanitarian Relief Operations Scale Up Emergency Food Aid in East Africa', 'නැගෙනහිර අප්‍රිකාවේ ආහාර හිඟය පවතින ප්‍රදේශ සඳහා ජාත්‍යන්තර ආධාර වැඩසටහන් කඩිනම් කෙරේ', 'கிழக்கு ஆபிரிக்காவில் உணவுத் தட்டுப்பாடு நிலவும் பகுதிகளுக்கு சர்வதேச நிவாரண உதவிகள் துரிதப்படுத்தப்பட்டன', 'Global Humanitarian Relief Operations Scale Up Emergency Food Aid in East Africa. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.', 'නැගෙනහිර අප්‍රිකාවේ ආහාර හිඟය පවතින ප්‍රදේශ සඳහා ජාත්‍යන්තර ආධාර වැඩසටහන් කඩිනම් කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.', 'கிழக்கு ஆபிரிக்காவில் உணவுத் தட்டுப்பாடு நிலவும் பகுதிகளுக்கு சர்வதேச நிவாரண உதவிகள் துரிதப்படுத்தப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.', '<p>Global Humanitarian Relief Operations Scale Up Emergency Food Aid in East Africa. Official briefings confirm comprehensive phased implementation with cross-sector stakeholder participation.</p><p>Speaking during a specialized press briefing in Colombo, key officials underscored the strategic importance of this national initiative. Extensive technical, financial, and regulatory frameworks have been finalized following consultations with international and domestic partners.</p><h3>Key Implementation Milestones</h3><p>The project will be deployed in carefully structured phases to ensure zero disruption to ongoing services while maximizing socio-economic benefits for citizens across the island. Independent oversight committees will periodically review milestones against established performance benchmarks.</p><blockquote>\"This milestone demonstrates our dedication to modern governance, sustainable infrastructure, and world-class public service delivery.\"</blockquote><p>Stakeholders across all provincial administration hubs have welcomed the move, noting that timely execution will significantly strengthen regional competitiveness and community welfare.</p>', '<p>නැගෙනහිර අප්‍රිකාවේ ආහාර හිඟය පවතින ප්‍රදේශ සඳහා ජාත්‍යන්තර ආධාර වැඩසටහන් කඩිනම් කෙරේ. අදාළ අංශ සමඟ සාකච්ඡා කරමින් මේ පිළිබඳ ඉදිරි ක්‍රියාමාර්ග කඩිනමින් ගැනීමට නියමිතය.</p><p>කොළඹ පැවති විශේෂ මාධ්‍ය හමුවකදී අදහස් දක්වමින් නිලධාරීන් සඳහන් කළේ මෙම ජාතික වැඩපිළිවෙළ මගින් සමස්ත රටවැසියන්ට සුවිශේෂී ප්‍රතිලාභ රැසක් අත්වන බවයි. දේශීය මෙන්ම ජාත්‍යන්තර ප්‍රමිතීන්ට අනුකූලව මෙහි සියලු කටයුතු සැලසුම් කර තිබේ.</p><h3>ක්‍රියාකාරී සැලැස්ම සහ ප්‍රතිලාභ</h3><p>අදාළ ක්ෂේත්‍රවල ප්‍රවීණයන්ගේ සහභාගීත්වයෙන් යුතුව ක්‍රමානුකූලව මෙම ව්‍යාපෘතිය ක්‍රියාත්මක කිරීමට පියවර ගෙන ඇති අතර, ඒ මගින් දිවයින පුරා ආර්ථික හා සමාජයීය සංවර්ධනයක් අපේක්ෂා කෙරේ.</p><blockquote>\"ජනතාවගේ යහපැවැත්ම උදෙසා මෙවැනි නවීන සහ විධිමත් පියවර ගැනීම කාලීන අවශ්‍යතාවයකි.\"</blockquote><p>ප්‍රාදේශීය මට්ටමින් ජනතා සහභාගීත්වය ලබාගනිමින් මෙම ව්‍යාපෘති කඩිනමින් අවසන් කිරීමට අපේක්ෂිතය.</p>', '<p>கிழக்கு ஆபிரிக்காவில் உணவுத் தட்டுப்பாடு நிலவும் பகுதிகளுக்கு சர்வதேச நிவாரண உதவிகள் துரிதப்படுத்தப்பட்டன. சம்பந்தப்பட்ட தரப்பினருடன் கலந்தாலோசித்து மேலதிக நடவடிக்கைகள் துரிதமாக முன்னெடுக்கப்படும்.</p><p>கொழும்பில் நடைபெற்ற விசேட ஊடகவியலாளர் சந்திப்பில் கருத்து வெளியிட்ட அதிகாரிகள், இந்த தேசிய வேலைத்திட்டத்தின் மூலம் பொதுமக்களுக்கு விரிவான நன்மைகள் கிடைக்கும் என தெரிவித்தனர்.</p><h3>முக்கிய திட்ட விபரங்கள்</h3><p>சர்வதேச மற்றும் உள்ளூர் தரநிலைகளுக்கு ஏற்ப அனைத்து நடவடிக்கைகளும் திட்டமிடப்பட்டுள்ளதுடன், எதிர்கால சந்ததியினரின் நலனையும் கருத்தில் கொண்டு இது நடைமுறைப்படுத்தப்படுகிறது.</p><blockquote>\"நாட்டின் நிலையான அபிவிருத்திக்கும் மக்களின் வாழ்வாதார மேம்பாட்டிற்கும் இவ்வாறான திட்டங்கள் இன்றியமையாதவை.\"</blockquote><p>அனைத்து மாகாண மட்டங்களிலும் உரிய ஒருங்கிணைப்புடன் இந்த திட்டம் வெற்றிகரமாக முன்னெடுக்கப்படும் என எதிர்பார்க்கப்படுகிறது.</p>', 'published', 0, 0, 0, 8946, '2026-09-25 23:41:00', '2026-09-25 23:41:00', '2026-09-25 23:41:00', '[]', '', 'National, Editorial, Lanka News Hub, News Edition') ON DUPLICATE KEY UPDATE `views` = VALUES(`views`);
